insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('give-and-drain-energy-week-map', 'Give and Drain Energy Week Map', 'worksheet'::resource_kind, 'A one-week planner where a client lists activities and marks which give and which drain energy.', 'Use it to help a client see how their week spends and restores energy.', array['Adults']::text[], 'One week', 'Walk through one ordinary day together first so the client can see how to mark each activity. Invite them to notice patterns without judging; the point is a picture of the week, not a grade. Bring it back and ask what surprised them.', '[{"id": "f0", "type": "textarea", "label": "List the main things you did each day this week:"}, {"id": "f1", "type": "textarea", "label": "Mark each one: gives energy, drains energy, or both."}, {"id": "f2", "type": "textarea", "label": "Which day felt most balanced, and why?"}, {"id": "f3", "type": "textarea", "label": "What is one small swap you could try next week?"}]'::jsonb, array['planning', 'self-monitoring']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('morning-and-evening-bookend-routine-sheet', 'Morning and Evening Bookend Routine Sheet', 'worksheet'::resource_kind, 'A sheet for choosing two short routines, one to open the day and one to close it.', 'Use it to help a client build a small, steady frame around the day.', array['Adults']::text[], '20 minutes', 'Keep each routine to three steps or fewer so it is realistic on a hard day. Ask the client to pick things they already do or genuinely want to do. Review after a week and trim whatever felt like a chore.', '[{"id": "f0", "type": "textarea", "label": "My three morning steps are:"}, {"id": "f1", "type": "textarea", "label": "My three evening steps are:"}, {"id": "f2", "type": "textarea", "label": "What could get in the way, and what is my backup plan?"}, {"id": "f3", "type": "textarea", "label": "How did each bookend feel after a week?"}]'::jsonb, array['routines', 'planning']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('who-helps-with-what-support-map', 'Who Helps With What Support Map', 'worksheet'::resource_kind, 'A page for sorting the people and places a client can turn to by the kind of help each offers.', 'Use it to help a client see the kinds of support already around them.', array['Adults']::text[], '25 minutes', 'Sort support by type, such as listening, practical help, fun or advice, so the client sees that different people fit different needs. Notice gaps without pushing; a gap is simply a place to explore next.', '[{"id": "f0", "type": "textarea", "label": "Who listens well when I need to talk?"}, {"id": "f1", "type": "textarea", "label": "Who helps with practical things?"}, {"id": "f2", "type": "textarea", "label": "Who is good company when I want to feel lighter?"}, {"id": "f3", "type": "textarea", "label": "Where do I see a gap I might want to fill?"}]'::jsonb, array['support', 'connection']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('choice-compass-three-column-sheet', 'Choice Compass Three-Column Sheet', 'worksheet'::resource_kind, 'A decision sheet with a third column asking which choice fits what matters to the client.', 'Use it to help a client weigh a choice against their own values, not only pros and cons.', array['Adults']::text[], '30 minutes', 'The values column is the part clients usually skip, so slow down there. Ask what they would be proud to have chosen in a year. Leave the final decision with the client.', '[{"id": "f0", "type": "textarea", "label": "The decision I am facing is:"}, {"id": "f1", "type": "textarea", "label": "Pros and cons of the first option:"}, {"id": "f2", "type": "textarea", "label": "Pros and cons of the second option:"}, {"id": "f3", "type": "textarea", "label": "Which option fits what matters most to me, and how?"}]'::jsonb, array['values', 'planning']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('small-win-capture-page', 'Small Win Capture Page', 'worksheet'::resource_kind, 'A daily page for recording one small thing that went acceptably and what made it possible.', 'Use it to help a client notice ordinary progress they tend to skip past.', array['Adults']::text[], 'Five minutes daily', 'Set the bar low on purpose: a win can be getting out of bed or sending one text. Ask what helped it happen, since that is the part worth repeating. Review a week of pages together.', '[{"id": "f0", "type": "textarea", "label": "Today one small thing went okay:"}, {"id": "f1", "type": "textarea", "label": "What helped it happen?"}, {"id": "f2", "type": "textarea", "label": "How did I feel right after?"}, {"id": "f3", "type": "textarea", "label": "What do I want to carry into tomorrow?"}]'::jsonb, array['strengths', 'self-monitoring']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('hot-thought-highlighter-record', 'Hot Thought Highlighter Record', 'cbt'::resource_kind, 'A thought record that has the client mark the single hottest thought and test only that one.', 'Use it to help a client focus a thought record on the belief doing most of the work.', array['Adults']::text[], '20 minutes', 'Many thought records stall because clients list five thoughts and test none. Have the client rate the heat of each and circle the highest. Then work through evidence for and against that one only.', '[{"id": "f0", "type": "textarea", "label": "The situation was:"}, {"id": "f1", "type": "textarea", "label": "Thoughts that came up, each with a heat rating from 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "Evidence that supports my hottest thought:"}, {"id": "f3", "type": "textarea", "label": "Evidence that does not fit it:"}, {"id": "f4", "type": "textarea", "label": "A more balanced version of the thought:"}]'::jsonb, array['core CBT', 'thinking traps']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('behavioral-experiment-planning-sheet', 'Behavioral Experiment Planning Sheet', 'cbt'::resource_kind, 'A step-by-step sheet for turning a prediction into a small, safe test with a clear outcome.', 'Use it to help a client test a belief through what they do, not just what they think.', array['Adults']::text[], '30 minutes', 'Choose a prediction specific enough to be wrong. Plan the experiment in session, agree on what would count as evidence, and keep the first one small. Debrief what actually happened versus what was predicted.', '[{"id": "f0", "type": "textarea", "label": "My prediction is:"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "The small test I will run, and when:"}, {"id": "f3", "type": "textarea", "label": "What actually happened?"}, {"id": "f4", "type": "textarea", "label": "What do I make of the gap between prediction and result?"}]'::jsonb, array['behavioral experiment', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('downward-arrow-question-ladder', 'Downward Arrow Question Ladder', 'cbt'::resource_kind, 'A ladder of "and if that were true, what would it mean" questions to reach an underlying belief.', 'Use it to help a client move from a surface worry to the belief beneath it.', array['Adults']::text[], '25 minutes', 'Go slowly and stay curious; the client may feel exposed when they reach the bottom of the ladder. Name the belief together in their words, then pause before challenging it. Close with something steadying.', '[{"id": "f0", "type": "textarea", "label": "The first worry I noticed is:"}, {"id": "f1", "type": "textarea", "label": "If that were true, what would it mean to me?"}, {"id": "f2", "type": "textarea", "label": "And if that were true, what would it say about me?"}, {"id": "f3", "type": "textarea", "label": "The belief at the bottom of the ladder, in my words:"}, {"id": "f4", "type": "textarea", "label": "How strongly do I believe it today, from 0 to 100?"}]'::jsonb, array['core CBT', 'thinking traps']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('pie-chart-responsibility-sort', 'Pie Chart Responsibility Sort', 'cbt'::resource_kind, 'A circle-slicing exercise for dividing up who or what contributed to an outcome.', 'Use it to help a client spread blame across everything that actually played a part.', array['Adults']::text[], '20 minutes', 'Ask the client to list contributing factors first and draw their own share last, so it is not the first slice they reach for. Gently notice factors outside their control. Revisit the chart if the feeling shifts.', '[{"id": "f0", "type": "textarea", "label": "The event I keep blaming myself for:"}, {"id": "f1", "type": "textarea", "label": "Everything that contributed, including things outside my control:"}, {"id": "f2", "type": "textarea", "label": "My share of the circle, drawn last:"}, {"id": "f3", "type": "textarea", "label": "How much responsibility do I feel now, from 0 to 100?"}]'::jsonb, array['thinking traps', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('activity-and-mood-grid-log', 'Activity and Mood Grid Log', 'cbt'::resource_kind, 'An hour-by-hour grid for logging what a client did and how it felt, to spot patterns.', 'Use it to give a client and clinician real data on what lifts and lowers mood.', array['Adults']::text[], 'One week', 'Show the client how to fill in a few entries in session and tell them that rough notes are fine. Look for patterns in activity, people and time of day together. Keep the tone curious.', '[{"id": "f0", "type": "textarea", "label": "What I was doing during each part of the day:"}, {"id": "f1", "type": "textarea", "label": "A mood rating for each, from 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "Which activities came with a higher rating?"}, {"id": "f3", "type": "textarea", "label": "What would I like to do more of this coming week?"}]'::jsonb, array['behavioral activation', 'self-monitoring']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('passengers-on-the-bus-role-play-page', 'Passengers on the Bus Role Play Page', 'act'::resource_kind, 'A worksheet for the bus metaphor: noisy passengers, one driver, and a direction chosen by values.', 'Use it to help a client keep driving toward what matters while difficult thoughts ride along.', array['Adults']::text[], '25 minutes', 'Act the metaphor out if the client is willing: you play the loud passengers while they hold a direction. Ask what each passenger says and what the driver does anyway. Keep it light and let humor in.', '[{"id": "f0", "type": "textarea", "label": "The direction I want to drive in is:"}, {"id": "f1", "type": "textarea", "label": "The loudest passengers and what they say:"}, {"id": "f2", "type": "textarea", "label": "What I usually do when they shout:"}, {"id": "f3", "type": "textarea", "label": "What I could do instead while they ride along:"}]'::jsonb, array['core ACT', 'defusion', 'values']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('hands-as-thoughts-distance-exercise', 'Hands as Thoughts Distance Exercise', 'act'::resource_kind, 'A brief exercise of holding hands over the face and then at arm length to feel distance from thoughts.', 'Use it to give a client a felt sense of stepping back from a stubborn thought.', array['Adults']::text[], '10 minutes', 'Invite the client to hold their hands over their face as if they were thoughts, notice what they can see, then lower them slowly. Ask what changed. Offer it as an experiment, not a fix.', '[{"id": "f0", "type": "textarea", "label": "A thought I get stuck on:"}, {"id": "f1", "type": "textarea", "label": "What I noticed with my hands over my face:"}, {"id": "f2", "type": "textarea", "label": "What changed with them lowered:"}, {"id": "f3", "type": "textarea", "label": "Where could I use this distance this week?"}]'::jsonb, array['defusion', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('values-card-sort-with-daily-actions', 'Values Card Sort With Daily Actions', 'act'::resource_kind, 'A card sort of values followed by one small action for each of a client''s top three.', 'Use it to help a client turn named values into things they can do this week.', array['Adults']::text[], '35 minutes', 'Let the client sort first by instinct, then slow down on the top three. Ask for actions small enough to do on a bad day. Remind them that values are directions, not goals to finish.', '[{"id": "f0", "type": "textarea", "label": "My top three values are:"}, {"id": "f1", "type": "textarea", "label": "What each one looks like in a small action today:"}, {"id": "f2", "type": "textarea", "label": "What tends to pull me away from each?"}, {"id": "f3", "type": "textarea", "label": "The action I will try first, and when:"}]'::jsonb, array['values', 'committed action']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('struggle-switch-awareness-log', 'Struggle Switch Awareness Log', 'act'::resource_kind, 'A log for catching moments of fighting a feeling and noticing what the fight costs.', 'Use it to help a client notice when struggling with a feeling adds to the weight of it.', array['Adults']::text[], 'One week', 'Introduce the idea of a switch that turns the struggle on or off, then log moments together. Ask what the struggle cost and what happened when it eased. Keep it a noticing task, not a performance.', '[{"id": "f0", "type": "textarea", "label": "The feeling I was fighting:"}, {"id": "f1", "type": "textarea", "label": "What the fight looked like:"}, {"id": "f2", "type": "textarea", "label": "What it cost me in that moment:"}, {"id": "f3", "type": "textarea", "label": "What happened when I made some room instead?"}]'::jsonb, array['willingness', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('present-moment-anchor-walk-page', 'Present Moment Anchor Walk Page', 'act'::resource_kind, 'A guided walking exercise with a page for what the client noticed through each sense.', 'Use it to help a client practice returning to the present in a simple, repeatable way.', array['Adults']::text[], '15 minutes', 'Walk slowly together or send the client out alone for five minutes. Ask for one thing noticed through each sense. When the mind wanders, that is simply the practice; invite them to return gently.', '[{"id": "f0", "type": "textarea", "label": "Something I saw:"}, {"id": "f1", "type": "textarea", "label": "Something I heard:"}, {"id": "f2", "type": "textarea", "label": "Something I felt through my feet or hands:"}, {"id": "f3", "type": "textarea", "label": "Where did my mind wander, and how did I come back?"}]'::jsonb, array['mindfulness', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-acting-on-urges-chart', 'Pros and Cons of Acting on Urges Chart', 'dbt'::resource_kind, 'A four-box pros and cons chart for acting on an urge versus tolerating it.', 'Use it to help a client weigh a strong urge against what they want for the longer run.', array['Adults']::text[], '25 minutes', 'Fill in all four boxes, including the short-term pros of the urge, so it feels honest. The chart works best made before a crisis point and kept handy. Ask the client where they will keep it.', '[{"id": "f0", "type": "textarea", "label": "The urge I am weighing:"}, {"id": "f1", "type": "textarea", "label": "Pros and cons of acting on it:"}, {"id": "f2", "type": "textarea", "label": "Pros and cons of tolerating it:"}, {"id": "f3", "type": "textarea", "label": "What I will do first next time it shows up:"}]'::jsonb, array['distress tolerance', 'core DBT', 'urges']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('feeling-versus-facts-opposite-step-page', 'Feeling Versus Facts Opposite Step Page', 'dbt'::resource_kind, 'A page for choosing an emotion, naming its urge, and trying an opposite action when it does not fit the facts.', 'Use it to help a client test an opposite action when a feeling does not match the situation.', array['Adults']::text[], '25 minutes', 'Check the facts first: opposite action fits when the feeling does not match what is happening. Choose an action small enough to try. Debrief what happened to the feeling afterward.', '[{"id": "f0", "type": "textarea", "label": "The emotion and how strong it is, from 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "Does it fit the facts? What are they?"}, {"id": "f2", "type": "textarea", "label": "What the emotion urges me to do:"}, {"id": "f3", "type": "textarea", "label": "The opposite action I will try, fully and all the way:"}, {"id": "f4", "type": "textarea", "label": "What happened to the feeling?"}]'::jsonb, array['emotion regulation', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('interpersonal-priorities-check-page', 'Interpersonal Priorities Check Page', 'dbt'::resource_kind, 'A page for deciding whether the goal, the relationship or self-respect matters most in a request.', 'Use it to help a client decide how hard to push in a conversation before they have it.', array['Adults']::text[], '20 minutes', 'Ask the client to rate the three priorities for a specific upcoming conversation. Then match the skills to the ratings. Clients often find self-respect is the one they forgot to weigh.', '[{"id": "f0", "type": "textarea", "label": "The conversation I am preparing for:"}, {"id": "f1", "type": "textarea", "label": "How much the goal matters, from 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "How much the relationship matters, from 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "How much my self-respect matters, from 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "What that tells me about how to ask:"}]'::jsonb, array['interpersonal effectiveness', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('turn-the-mind-toward-what-is-daily-log', 'Turn the Mind Toward What Is Daily Log', 'dbt'::resource_kind, 'A log for the moments of refusing reality and the small choices to turn the mind back toward acceptance.', 'Use it to help a client notice when they resist what is and practice turning toward it.', array['Adults']::text[], 'One week', 'Name that acceptance is not approval; it is stopping the fight with the facts. Have the client log moments of resistance and what turning the mind looked like. Be gentle with slow progress.', '[{"id": "f0", "type": "textarea", "label": "The thing I am struggling to accept:"}, {"id": "f1", "type": "textarea", "label": "How I know I am resisting it:"}, {"id": "f2", "type": "textarea", "label": "What turning my mind toward it looked like:"}, {"id": "f3", "type": "textarea", "label": "What I could do next that helps me cope with it:"}]'::jsonb, array['acceptance', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('tipp-skills-practice-card-set', 'TIPP Skills Practice Card Set', 'dbt'::resource_kind, 'A set of cards for the temperature, intense exercise, paced breathing and paired muscle relaxation skills.', 'Use it to give a client a menu of fast body-based skills for high arousal.', array['Adults']::text[], '30 minutes', 'Practice each skill briefly in session so the client knows what it feels like before they need it. Check for any health considerations before cold or intense exercise and leave that choice to the client. Pick one to keep in a pocket.', '[{"id": "f0", "type": "textarea", "label": "The skill I tried first and how it felt:"}, {"id": "f1", "type": "textarea", "label": "My arousal before and after, from 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "Which skill suited me best?"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the card:"}]'::jsonb, array['distress tolerance', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('turn-toward-bids-daily-log-for-two', 'Turn Toward Bids Daily Log for Two', 'couples'::resource_kind, 'A shared log where each partner notes small bids for attention and how the other responded.', 'Use it to help partners notice and answer the small moments that build closeness.', array['Couples']::text[], 'One week', 'Explain a bid as any small reach for attention, from a comment about a bird to a sigh. Each partner logs their own bids and responses separately. Review together and appreciate the ones that landed.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a bid I made today and how it was met:"}, {"id": "f1", "type": "textarea", "label": "Partner B: a bid I made today and how it was met:"}, {"id": "f2", "type": "textarea", "label": "A bid I noticed from my partner and how I responded:"}, {"id": "f3", "type": "textarea", "label": "One response I would like to try next time:"}]'::jsonb, array['Gottman', 'communication', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('stress-relief-check-in-card-set', 'Stress-Relief Check-In Card Set', 'couples'::resource_kind, 'Cards that guide partners to listen to each other''s outside stress without giving advice.', 'Use it to help partners support each other through stress that did not come from the relationship.', array['Couples']::text[], '20 minutes', 'Have partners take turns speaking and listening for ten minutes each, with the listener asking questions and staying on the speaker''s side. Advice waits for an invitation. Debrief what felt supportive.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the stress I carried today is:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can say to show I am on your side:"}, {"id": "f2", "type": "textarea", "label": "Partner B: the stress I carried today is:"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I can say to show I am on your side:"}]'::jsonb, array['connection', 'communication', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('our-small-rituals-idea-swap', 'Our Small Rituals Idea Swap', 'couples'::resource_kind, 'A brainstorm for small recurring rituals that give a couple a sense of shared meaning.', 'Use it to help partners create a few regular rituals that feel like theirs.', array['Couples']::text[], '30 minutes', 'Ask each partner to think of rituals from childhood and from the relationship, then choose one or two to start. Small and regular beats grand and rare. Check in on how it feels after two weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a ritual I treasure or would like to start:"}, {"id": "f1", "type": "textarea", "label": "Partner B: a ritual I treasure or would like to start:"}, {"id": "f2", "type": "textarea", "label": "Which one will we begin, and when?"}, {"id": "f3", "type": "textarea", "label": "How will we know it is working for both of us?"}]'::jsonb, array['connection', 'couples', 'planning']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('soft-startup-rewrite-practice-page', 'Soft Startup Rewrite Practice Page', 'couples'::resource_kind, 'A page for turning a harsh opening line into a gentler one that still names the need.', 'Use it to help partners raise a concern in a way the other can hear.', array['Couples']::text[], '20 minutes', 'Have each partner bring a real recent opener and rewrite it into a feeling, a situation and a request. Practice saying it aloud in session. Notice the tone that helps and the one that does not.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I opened last time:"}, {"id": "f1", "type": "textarea", "label": "Partner A: my softer version (I feel... about... I need...):"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I opened last time:"}, {"id": "f3", "type": "textarea", "label": "Partner B: my softer version (I feel... about... I need...):"}]'::jsonb, array['communication', 'couples', 'Gottman']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('appreciation-jar-weekly-ritual-sheet', 'Appreciation Jar Weekly Ritual Sheet', 'couples'::resource_kind, 'A sheet for setting up a jar where partners drop notes of appreciation and read them weekly.', 'Use it to help partners build a steady habit of noticing what they value in each other.', array['Couples']::text[], 'One week', 'Keep the notes specific, such as "thank you for making coffee" rather than general praise. Agree on a day to read them aloud together. Check afterward which notes meant the most.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three things I appreciated this week:"}, {"id": "f1", "type": "textarea", "label": "Partner B: three things I appreciated this week:"}, {"id": "f2", "type": "textarea", "label": "Which note meant the most to us, and why?"}, {"id": "f3", "type": "textarea", "label": "When will we read the notes together?"}]'::jsonb, array['connection', 'couples', 'support']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('paper-plate-mood-pointer-craft', 'Paper Plate Mood Pointer Craft', 'kids'::resource_kind, 'Children build a paper weather station and move a pointer to show how they feel today.', 'Use it to give a child an easy, playful way to show feelings without needing words.', array['Children']::text[], '30 minutes', 'The child decorates a paper plate with sun, cloud, rain and storm sections and a paper arrow. The parent joins in and checks the arrow at a calm time each day. Respond with interest and curiosity rather than fixing.', '[{"id": "f0", "type": "textarea", "label": "Draw your feelings weather today:"}, {"id": "f1", "type": "textarea", "label": "The weather you see most often:"}, {"id": "f2", "type": "textarea", "label": "What helps when it gets stormy?"}, {"id": "f3", "type": "textarea", "label": "What did parent notice on the station this week?"}]'::jsonb, array['children', 'art', 'emotion identification']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('brave-badge-design-page', 'Brave Badge Design Page', 'kids'::resource_kind, 'A page where a child designs a badge for something they were brave about.', 'Use it to help a child notice and take pride in their own acts of courage.', array['Children']::text[], '20 minutes', 'The child draws a badge and names what it is for, big or small. The parent adds one brave thing they noticed. Display the badge where the child sees it and add a new one when it fits.', '[{"id": "f0", "type": "textarea", "label": "Draw your brave badge:"}, {"id": "f1", "type": "textarea", "label": "What did you do that was brave?"}, {"id": "f2", "type": "textarea", "label": "How did your body feel afterward?"}, {"id": "f3", "type": "textarea", "label": "What did parent notice about your bravery?"}]'::jsonb, array['children', 'strengths', 'art']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('calm-down-spot-builder', 'Calm Down Spot Builder', 'kids'::resource_kind, 'Children and a parent set up a cozy corner and fill it with things that help them settle.', 'Use it to help a child have a safe place of their own to settle when upset.', array['Children']::text[], '45 minutes', 'The spot is a choice, never a punishment. The child picks the pillows, pictures and tools; the parent practices using it together when calm. Aim to have the child go there on their own over time.', '[{"id": "f0", "type": "textarea", "label": "Draw your calm down spot:"}, {"id": "f1", "type": "textarea", "label": "Three things I want in it:"}, {"id": "f2", "type": "textarea", "label": "How I know it is time to go there:"}, {"id": "f3", "type": "textarea", "label": "What parent does when I am in my spot:"}]'::jsonb, array['children', 'coping skills', 'play']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('kindness-detective-mission-sheet', 'Kindness Detective Mission Sheet', 'kids'::resource_kind, 'A play mission where a child watches for kind acts in the family and records them as clues.', 'Use it to help a child notice kindness around them and practice offering it.', array['Children']::text[], 'One week', 'The child is the detective and the parent leaves clues too. Keep the tone playful and give no prizes for tallies. Share the findings at dinner or bedtime.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I spotted:"}, {"id": "f1", "type": "textarea", "label": "Who did it?"}, {"id": "f2", "type": "textarea", "label": "A kind thing I did this week:"}, {"id": "f3", "type": "textarea", "label": "How it felt to notice kindness:"}]'::jsonb, array['children', 'connection', 'play']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('thought-bubble-comic-strip', 'Thought Bubble Comic Strip', 'kids'::resource_kind, 'Children draw a short comic where a character has a worried thought bubble and a helpful one.', 'Use it to help a child see that thoughts can change and that more than one is possible.', array['Children']::text[], '30 minutes', 'The child draws three panels: the event, the worry thought and a kinder or braver one. The parent asks what the character would say to a friend. Let the child lead the story and the drawing.', '[{"id": "f0", "type": "textarea", "label": "Draw what happened in panel one:"}, {"id": "f1", "type": "textarea", "label": "Draw the worry thought bubble:"}, {"id": "f2", "type": "textarea", "label": "Draw a helpful thought bubble:"}, {"id": "f3", "type": "textarea", "label": "What did parent say about your comic?"}]'::jsonb, array['children', 'thinking traps', 'art']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('skill-spinner-party-game', 'Skill Spinner Party Game', 'game'::resource_kind, 'A spinner game where each spin names a coping skill to demonstrate or teach to the group.', 'Use it to help a group rehearse coping skills in a lively, low-pressure way.', array['Groups']::text[], '30 minutes', 'Make a spinner with eight skills, such as breathing or grounding. Each player demonstrates their skill, and the group adds when they would use it. Debrief what surprised people and which skill they will try.', '[{"id": "f0", "type": "textarea", "label": "The skill I got and how I showed it:"}, {"id": "f1", "type": "textarea", "label": "A moment I could use it:"}, {"id": "f2", "type": "textarea", "label": "A skill someone else showed me that I liked:"}, {"id": "f3", "type": "textarea", "label": "What I will try this week:"}]'::jsonb, array['game', 'coping skills', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('values-auction-table-game', 'Values Auction Table Game', 'game'::resource_kind, 'Players bid pretend coins on values and discuss what they were willing to spend on.', 'Use it to help players see which values they would give up the most for.', array['Groups']::text[], '40 minutes', 'Give each player the same number of coins and a list of values to bid on. After each round, ask what drove their bids. Debrief gently, since some players feel uneasy when a value goes unbought.', '[{"id": "f0", "type": "textarea", "label": "The value I spent the most on:"}, {"id": "f1", "type": "textarea", "label": "One I wanted but did not win:"}, {"id": "f2", "type": "textarea", "label": "What my bidding says about me:"}, {"id": "f3", "type": "textarea", "label": "Something I want to do about it:"}]'::jsonb, array['values', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('balanced-reply-team-relay', 'Balanced Reply Team Relay', 'game'::resource_kind, 'Teams pass cards with stuck thoughts and race to write a more balanced reply.', 'Use it to help a group practice generating balanced thoughts together.', array['Groups']::text[], '30 minutes', 'Write stuck thoughts on cards, then teams take turns reading one and writing a kinder, more balanced reply. Points go for honesty rather than speed. Debrief which replies felt believable.', '[{"id": "f0", "type": "textarea", "label": "The stuck thought I got:"}, {"id": "f1", "type": "textarea", "label": "The reply our team wrote:"}, {"id": "f2", "type": "textarea", "label": "Which reply felt most believable and why?"}, {"id": "f3", "type": "textarea", "label": "A thought of my own I want to reframe:"}]'::jsonb, array['thinking traps', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('silent-feelings-acting-game', 'Silent Feelings Acting Game', 'game'::resource_kind, 'Players act out an emotion without speaking while others guess and name its clues.', 'Use it to help a group notice how feelings show up in the body and face.', array['Groups']::text[], '25 minutes', 'Each player draws an emotion card and acts it out. The group guesses and names which clues gave it away. Debrief the body signs people noticed and when they feel them.', '[{"id": "f0", "type": "textarea", "label": "The emotion I acted out:"}, {"id": "f1", "type": "textarea", "label": "The clues the group noticed:"}, {"id": "f2", "type": "textarea", "label": "How I feel this emotion in my body:"}, {"id": "f3", "type": "textarea", "label": "One time I noticed it this week:"}]'::jsonb, array['game', 'emotion identification', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('strengths-scavenger-hunt-game', 'Strengths Scavenger Hunt Game', 'game'::resource_kind, 'Players hunt for evidence of strengths in themselves and one another using prompt cards.', 'Use it to help players find and name strengths they tend to overlook.', array['Groups']::text[], '35 minutes', 'Each prompt card asks for a time they showed a strength, such as patience or humor. Players hunt through memory and notice others. Debrief how it felt to hear what others saw.', '[{"id": "f0", "type": "textarea", "label": "A strength I found in myself:"}, {"id": "f1", "type": "textarea", "label": "A time I showed it:"}, {"id": "f2", "type": "textarea", "label": "A strength someone else noticed in me:"}, {"id": "f3", "type": "textarea", "label": "How I can use it this week:"}]'::jsonb, array['strengths', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('window-of-comfort-pacing-gauge', 'Window of Comfort Pacing Gauge', 'worksheet'::resource_kind, 'A gauge page for noticing when a client is too revved, too shut down, or in a workable zone.', 'Use it to help a client pace a session by naming where they are right now.', array['Adults']::text[], '20 minutes', 'Introduce the three zones using the client''s own words for each. Check the gauge at the start, middle and end of sessions, and slow down or ground when they leave the workable zone. The page is about pacing, never about going into details.', '[{"id": "f0", "type": "textarea", "label": "What does too revved feel like in my body?"}, {"id": "f1", "type": "textarea", "label": "What does too shut down feel like?"}, {"id": "f2", "type": "textarea", "label": "What does a workable zone feel like?"}, {"id": "f3", "type": "textarea", "label": "Right now I am in this zone, and one thing that helps me stay is:"}]'::jsonb, array['PTSD and trauma', 'pacing', 'safety']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('safety-versus-danger-present-check-cards', 'Safety Versus Danger Present Check Cards', 'cbt'::resource_kind, 'Cards that help a client tell the difference between a reminder and danger in the present moment.', 'Use it to help a client check what is happening now when a reminder pulls them back.', array['Adults']::text[], '25 minutes', 'Work only with the present: what is around me, what is different now. Never ask for the details of what happened. Practice with mild reminders first and end with grounding.', '[{"id": "f0", "type": "textarea", "label": "Something that reminded me of the past today:"}, {"id": "f1", "type": "textarea", "label": "What is actually around me right now?"}, {"id": "f2", "type": "textarea", "label": "What is different about now?"}, {"id": "f3", "type": "textarea", "label": "What I can say to myself to stay in the present:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('choosing-direction-after-hard-times-values-page', 'Choosing Direction After Hard Times Values Page', 'act'::resource_kind, 'A page for naming what a client wants their life to stand for, without revisiting what happened.', 'Use it to help a client reconnect with direction and meaning at their own pace.', array['Adults']::text[], '30 minutes', 'Stay in the present and future; the page never needs a recounting of the past. Let the client choose one value and one small step. Check in about how it felt and slow down if needed.', '[{"id": "f0", "type": "textarea", "label": "A part of life I want to care about again:"}, {"id": "f1", "type": "textarea", "label": "What this would look like in a small step:"}, {"id": "f2", "type": "textarea", "label": "What might get in the way?"}, {"id": "f3", "type": "textarea", "label": "Who or what could support me with this?"}]'::jsonb, array['PTSD and trauma', 'values', 'committed action']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('sense-by-sense-calming-box-plan', 'Sense-by-Sense Calming Box Plan', 'dbt'::resource_kind, 'A plan for assembling a small kit of items that calm each sense.', 'Use it to help a client prepare calming tools before they are needed.', array['Adults']::text[], '30 minutes', 'Have the client choose one item per sense and try it in session. Ask which ones work best and which feel odd. Keep the kit somewhere easy to reach and revisit it as tastes change.', '[{"id": "f0", "type": "textarea", "label": "Something calming to see:"}, {"id": "f1", "type": "textarea", "label": "Something calming to hear:"}, {"id": "f2", "type": "textarea", "label": "Something calming to touch, smell or taste:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep my kit:"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'grounding', 'self-soothe']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('partner-support-plan-for-hard-moments', 'Partner Support Plan for Hard Moments', 'couples'::resource_kind, 'A plan for partners that names what helps and what does not when one of them is overwhelmed.', 'Use it to help partners agree on simple ways to support each other without pushing for details.', array['Couples']::text[], '30 minutes', 'Each partner says what helps in plain words, such as a quiet presence or a glass of water, and what does not. Remind partners that nobody needs to tell the story for the plan to work. Practice once in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me when I am overwhelmed:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can do to be there:"}, {"id": "f3", "type": "textarea", "label": "What word or signal will we use?"}]'::jsonb, array['PTSD and trauma', 'support', 'safety', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('what-would-i-tell-a-friend-worry-reply-sheet', 'What Would I Tell a Friend Worry Reply Sheet', 'cbt'::resource_kind, 'A sheet where a client writes the reply they would offer a friend with their same worry.', 'Use it to help a client borrow kinder, steadier advice for their own anxious thoughts.', array['Adults']::text[], '20 minutes', 'Ask for the worry first in the client''s exact words, then the friend''s version. Notice any difference in tone. Invite the client to read the reply back as if to themselves.', '[{"id": "f0", "type": "textarea", "label": "My worry, in my own words:"}, {"id": "f1", "type": "textarea", "label": "If a friend told me this, I would say:"}, {"id": "f2", "type": "textarea", "label": "What is different about how I speak to myself?"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself next time:"}]'::jsonb, array['anxiety', 'worry', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('anxiety-as-a-passenger-experiment-page', 'Anxiety as a Passenger Experiment Page', 'act'::resource_kind, 'A page for letting anxiety come along on a trip toward something the client cares about.', 'Use it to help a client act on what matters while anxiety is present.', array['Adults']::text[], '25 minutes', 'Pick one small action the client cares about and invite anxiety along. The measure is the action, not the anxiety level. Debrief what it was like to do it with the passenger present.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me that anxiety gets in the way of:"}, {"id": "f1", "type": "textarea", "label": "One small step I can take with anxiety along:"}, {"id": "f2", "type": "textarea", "label": "What I noticed while I took it:"}, {"id": "f3", "type": "textarea", "label": "What I want to do next:"}]'::jsonb, array['anxiety', 'willingness', 'values']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('wise-worry-versus-loud-worry-sorting-page', 'Wise Worry Versus Loud Worry Sorting Page', 'dbt'::resource_kind, 'A sort for deciding which worries call for a plan and which call for letting go.', 'Use it to help a client separate worries they can act on from those they cannot.', array['Adults']::text[], '25 minutes', 'Have the client list the week''s worries and sort them into act now, plan later and let pass. Add one skill for each pile. Be curious about what keeps the let-pass pile from feeling easy.', '[{"id": "f0", "type": "textarea", "label": "The worries I had this week:"}, {"id": "f1", "type": "textarea", "label": "The ones I can act on:"}, {"id": "f2", "type": "textarea", "label": "The ones I can only let pass:"}, {"id": "f3", "type": "textarea", "label": "A skill I will use for each pile:"}]'::jsonb, array['anxiety', 'regulation', 'worry', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('anxiety-check-in-conversation-guide', 'Anxiety Check-In Conversation Guide', 'couples'::resource_kind, 'A guide for a partner who feels anxious and one who wants to help without fixing.', 'Use it to help partners talk about anxiety in a way that feels supportive to both.', array['Couples']::text[], '25 minutes', 'Have the anxious partner say what they need, such as listening or distraction, and the other say what they can offer. Avoid reassurance that becomes a loop. Practice once and note what felt good.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need when anxiety is high:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer, and what I would rather not do:"}, {"id": "f2", "type": "textarea", "label": "What phrase will help us both stay calm?"}, {"id": "f3", "type": "textarea", "label": "How will we check in on how this is working?"}]'::jsonb, array['anxiety', 'communication', 'support', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('worry-shrinking-wand-craft', 'Worry-Shrinking Wand Craft', 'kids'::resource_kind, 'Children make a wand and invent a silly spell to shrink a worry.', 'Use it to help a child have a playful way to talk back to a worry.', array['Children']::text[], '30 minutes', 'The child decorates a wand and makes up a spell that shrinks the worry. The parent plays along without arguing the worry away. Keep it silly and use it at a calm moment before using it in a hard one.', '[{"id": "f0", "type": "textarea", "label": "Draw your worry as something small and silly:"}, {"id": "f1", "type": "textarea", "label": "What spell will shrink it?"}, {"id": "f2", "type": "textarea", "label": "When could the wand come out?"}, {"id": "f3", "type": "textarea", "label": "What did parent say about your wizard skills?"}]'::jsonb, array['anxiety', 'children', 'worry', 'play']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('small-steps-toward-values-on-heavy-days-page', 'Small Steps Toward Values on Heavy Days Page', 'act'::resource_kind, 'A page for picking one tiny action tied to a value even when motivation is low.', 'Use it to help a client act in line with a value before the mood lifts.', array['Adults']::text[], '25 minutes', 'Do not wait for motivation; pick an action small enough to take at low energy. Link it to a named value, so it feels purposeful and not a chore. Check back on what happened and what got in the way.', '[{"id": "f0", "type": "textarea", "label": "A value I want to keep close:"}, {"id": "f1", "type": "textarea", "label": "A tiny action that fits it:"}, {"id": "f2", "type": "textarea", "label": "What I will do and when:"}, {"id": "f3", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['depression', 'values', 'behavioral activation']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('build-positive-moments-short-term-plan', 'Build Positive Moments Short-Term Plan', 'dbt'::resource_kind, 'A plan for adding a few small pleasant moments to the week and noticing them fully.', 'Use it to help a client add small positive moments and pay attention to them.', array['Adults']::text[], '25 minutes', 'Choose things that are easy to reach, even ten minutes long. Ask the client to stay present while doing them rather than thinking about what is missing. Review which ones felt best.', '[{"id": "f0", "type": "textarea", "label": "Small things that bring any bit of pleasure:"}, {"id": "f1", "type": "textarea", "label": "Three I will do this week:"}, {"id": "f2", "type": "textarea", "label": "How I stayed present while doing one:"}, {"id": "f3", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['depression', 'emotion regulation', 'core DBT', 'behavioral activation']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('reaching-toward-a-low-mood-partner-guide', 'Reaching Toward a Low Mood Partner Guide', 'couples'::resource_kind, 'A guide for partners on offering company without pressure when one person feels low.', 'Use it to help partners stay connected while one of them is low.', array['Couples']::text[], '25 minutes', 'Help the partner who is low name what kinds of company feel okay and which do not. Help the other offer small invitations without pressure. Normalize that the person may say no sometimes.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what kind of company helps when I am low:"}, {"id": "f1", "type": "textarea", "label": "Partner B: small invitations I can offer:"}, {"id": "f2", "type": "textarea", "label": "What we will do if one of us says no:"}, {"id": "f3", "type": "textarea", "label": "How we will check in about this next week:"}]'::jsonb, array['depression', 'support', 'connection', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('mood-garden-drawing-journal', 'Mood Garden Drawing Journal', 'kids'::resource_kind, 'Children draw a garden whose flowers grow or rest to show how they feel through the week.', 'Use it to give a child a gentle, visual way to track feelings and what helps them grow.', array['Children']::text[], '20 minutes daily', 'The child colors one flower per day for the mood they feel and adds something that helped, like sun or water. The parent looks at it together without asking why. Take notes of patterns to share in session.', '[{"id": "f0", "type": "textarea", "label": "Color one flower for today:"}, {"id": "f1", "type": "textarea", "label": "What helped it grow today?"}, {"id": "f2", "type": "textarea", "label": "Draw something that makes your garden brighter:"}, {"id": "f3", "type": "textarea", "label": "What did parent notice in your garden?"}]'::jsonb, array['depression', 'children', 'art', 'self-monitoring']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('energy-level-check-in-game-for-groups', 'Energy Level Check-In Game for Groups', 'game'::resource_kind, 'A group game of moving to a spot on the room to show energy and sharing what shifts it.', 'Use it to help a group talk about energy and low mood in a light, active way.', array['Groups']::text[], '25 minutes', 'Mark a line in the room from low to high energy and ask people to stand where they are. Ask what moves them one step along. Debrief and notice that it is fine to stay where you are.', '[{"id": "f0", "type": "textarea", "label": "Where I stood and why:"}, {"id": "f1", "type": "textarea", "label": "What moves my energy up a little:"}, {"id": "f2", "type": "textarea", "label": "What moves it down:"}, {"id": "f3", "type": "textarea", "label": "A step I will try this week:"}]'::jsonb, array['depression', 'game', 'group', 'behavioral activation']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('pause-before-acting-skill-practice-sheet', 'Pause Before Acting Skill Practice Sheet', 'dbt'::resource_kind, 'A sheet for practicing a short pause and a choice before acting on a strong impulse.', 'Use it to help a client build a brief gap between urge and action.', array['Adults']::text[], '20 minutes', 'Practice the pause in session with a low-stakes example. Ask the client to choose a cue, like a breath or a phrase. Build up to harder moments and celebrate each pause, however short.', '[{"id": "f0", "type": "textarea", "label": "A time I acted before thinking this week:"}, {"id": "f1", "type": "textarea", "label": "What my pause cue will be:"}, {"id": "f2", "type": "textarea", "label": "What I could do in the pause:"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it?"}]'::jsonb, array['ADHD', 'regulation', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('fair-share-household-load-planning-sheet', 'Fair Share Household Load Planning Sheet', 'couples'::resource_kind, 'A sheet for partners to split household tasks in a way both can see and keep.', 'Use it to help partners divide household tasks visibly and fairly.', array['Couples']::text[], '30 minutes', 'Ask both partners to list all tasks, including the invisible ones, then divide by preference and capacity. Use reminders and visible lists rather than nagging. Revisit after two weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I can take on:"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I can take on:"}, {"id": "f2", "type": "textarea", "label": "Tasks we have to negotiate:"}, {"id": "f3", "type": "textarea", "label": "What reminder system will we use?"}]'::jsonb, array['ADHD', 'planning', 'routines', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('task-sequence-picture-cards-build', 'Task Sequence Picture Cards Build', 'kids'::resource_kind, 'Children and a parent make picture cards for a morning or homework routine.', 'Use it to help a child see the steps of a routine in a form they can follow.', array['Children']::text[], '45 minutes', 'The child draws or photographs each step and helps put them in order. The parent hangs the cards where the routine happens and cheers on each flip. Update cards when something changes.', '[{"id": "f0", "type": "textarea", "label": "Draw the first step of the routine:"}, {"id": "f1", "type": "textarea", "label": "Draw the next step:"}, {"id": "f2", "type": "textarea", "label": "Which step is hardest for me?"}, {"id": "f3", "type": "textarea", "label": "What can parent do to help with it?"}]'::jsonb, array['ADHD', 'children', 'routines', 'play']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('beat-the-timer-task-blitz-game', 'Beat the Timer Task Blitz Game', 'game'::resource_kind, 'A timed game where players guess how long tasks will take and then try them.', 'Use it to help players practice time estimates in a playful setting.', array['Groups']::text[], '30 minutes', 'Players guess how long small tasks will take before trying them, then compare. Debrief what they learn about their sense of time. Keep competition light and celebrate good guesses and funny misses.', '[{"id": "f0", "type": "textarea", "label": "My guess and the real time for one task:"}, {"id": "f1", "type": "textarea", "label": "What surprised me?"}, {"id": "f2", "type": "textarea", "label": "What does this tell me about planning my time?"}, {"id": "f3", "type": "textarea", "label": "One task I will time this week:"}]'::jsonb, array['ADHD', 'game', 'planning', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('sunday-reset-planning-sheet', 'Sunday Reset Planning Sheet', 'worksheet'::resource_kind, 'A sheet for planning the coming week on Sunday, with three priorities and a backup plan.', 'Use it to help a client start the week with a few clear priorities.', array['Adults']::text[], '25 minutes', 'Keep it to three priorities and one backup plan so it does not become a long list. Have the client put it where they will see it. Ask what usually derails a plan and build that in.', '[{"id": "f0", "type": "textarea", "label": "My three priorities this week:"}, {"id": "f1", "type": "textarea", "label": "When I will do each one:"}, {"id": "f2", "type": "textarea", "label": "What usually gets in the way?"}, {"id": "f3", "type": "textarea", "label": "My backup plan if the week goes sideways:"}]'::jsonb, array['ADHD', 'routines', 'planning']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('talking-about-substance-use-without-blame-guide', 'Talking About Substance Use Without Blame Guide', 'couples'::resource_kind, 'A guide for partners on raising worries about substance use in a calm, specific way.', 'Use it to help partners talk about substance use with care and without blame.', array['Couples']::text[], '30 minutes', 'Have partners practice describing what they notice and how it affects them, not labeling the person. The partner with the substance use names what they want from support. Slow down if it heats up.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I have noticed and how it affects me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I want my partner to know about how this feels:"}, {"id": "f2", "type": "textarea", "label": "What kind of support do we each want?"}, {"id": "f3", "type": "textarea", "label": "What is one step we can take together?"}]'::jsonb, array['addiction', 'communication', 'support', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('urge-wave-rider-timer-game', 'Urge Wave Rider Timer Game', 'game'::resource_kind, 'A group game of riding out a pretend urge wave while playing a simple distraction.', 'Use it to help players practice noticing urges rise and fall without acting on them.', array['Groups']::text[], '30 minutes', 'Use a timer and a simple game like card sorting while players rate a pretend urge. Players notice how it rises and eases. Debrief what helped and plan one skill for real urges.', '[{"id": "f0", "type": "textarea", "label": "My urge rating at the start, middle and end:"}, {"id": "f1", "type": "textarea", "label": "What I noticed as the wave moved:"}, {"id": "f2", "type": "textarea", "label": "What helped it pass:"}, {"id": "f3", "type": "textarea", "label": "Where I will use it next:"}]'::jsonb, array['addiction', 'urges', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('substance-use-pattern-triggers-map', 'Substance Use Pattern Triggers Map', 'worksheet'::resource_kind, 'A map for noting when, where and with whom urges to use tend to appear.', 'Use it to help a client see the patterns around urges so they can plan ahead.', array['Adults']::text[], '25 minutes', 'Have the client fill the map in from a recent week with no judgment. Look for times, places and feelings that come up often. Choose one pattern and plan one small change together.', '[{"id": "f0", "type": "textarea", "label": "Times of day urges tend to come up:"}, {"id": "f1", "type": "textarea", "label": "Places or people connected to them:"}, {"id": "f2", "type": "textarea", "label": "Feelings that come before them:"}, {"id": "f3", "type": "textarea", "label": "One change I could try:"}]'::jsonb, array['addiction', 'urges', 'self-monitoring', 'planning']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('just-this-once-thought-record', 'Just This Once Thought Record', 'cbt'::resource_kind, 'A record for the thoughts that come with an urge and a balanced reply.', 'Use it to help a client examine the thoughts that push them toward using.', array['Adults']::text[], '20 minutes', 'Ask for the exact thought that comes with an urge, such as "just this once." Look at what it leaves out. Practice the reply aloud and plan where to keep it.', '[{"id": "f0", "type": "textarea", "label": "The urge I noticed and what I was doing:"}, {"id": "f1", "type": "textarea", "label": "The thought that came with it:"}, {"id": "f2", "type": "textarea", "label": "What that thought leaves out:"}, {"id": "f3", "type": "textarea", "label": "A reply I can use next time:"}]'::jsonb, array['addiction', 'urges', 'core CBT', 'thinking traps']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('making-room-for-urges-willingness-page', 'Making Room for Urges Willingness Page', 'act'::resource_kind, 'A page for allowing an urge to be present while choosing an action that fits a value.', 'Use it to help a client carry an urge without acting on it while moving toward what matters.', array['Adults']::text[], '25 minutes', 'Describe the urge as a wave that can be watched. Ask the client to name a value and an action that fits it. Debrief what happened when they let the urge be there.', '[{"id": "f0", "type": "textarea", "label": "The urge I notice and where it lives in my body:"}, {"id": "f1", "type": "textarea", "label": "What I care about that matters more:"}, {"id": "f2", "type": "textarea", "label": "What I will do while it is there:"}, {"id": "f3", "type": "textarea", "label": "What happened?"}]'::jsonb, array['addiction', 'urges', 'willingness', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('volcano-cool-down-craft-and-plan', 'Volcano Cool-Down Craft and Plan', 'kids'::resource_kind, 'Children build a paper volcano and plan what to do as the heat rises.', 'Use it to help a child learn to notice anger early and choose a calming step.', array['Children']::text[], '45 minutes', 'The child draws levels from calm to eruption and adds a cool-down tool at each level. The parent practices one with the child when calm. Never use the volcano to shame an outburst.', '[{"id": "f0", "type": "textarea", "label": "Draw your volcano and mark where you feel hot:"}, {"id": "f1", "type": "textarea", "label": "What my body does when it heats up:"}, {"id": "f2", "type": "textarea", "label": "What I can do at each level:"}, {"id": "f3", "type": "textarea", "label": "What parent will do to help:"}]'::jsonb, array['anger management', 'children', 'coping skills', 'play']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('pause-and-respond-role-play-cards', 'Pause and Respond Role Play Cards', 'game'::resource_kind, 'A card game of acting out common irritations and practicing a calm response.', 'Use it to help a group rehearse calm responses to common triggers.', array['Groups']::text[], '35 minutes', 'Players draw a situation, act the first reaction and then try a calmer one. Others offer what they noticed. Debrief how the second try felt in the body.', '[{"id": "f0", "type": "textarea", "label": "The situation I got:"}, {"id": "f1", "type": "textarea", "label": "My first reaction and my calmer one:"}, {"id": "f2", "type": "textarea", "label": "What changed in my body?"}, {"id": "f3", "type": "textarea", "label": "Where I could use this week:"}]'::jsonb, array['anger management', 'game', 'group', 'regulation']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('early-heat-signals-body-outline', 'Early Heat Signals Body Outline', 'worksheet'::resource_kind, 'A body outline where a client marks where and how anger shows up before it peaks.', 'Use it to help a client notice the early body signals of anger.', array['Adults']::text[], '20 minutes', 'Ask the client to shade where they feel anger and describe it, such as heat or a tight jaw. Rank signs from earliest to latest. Link the earliest sign to one pause they can try.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anger first:"}, {"id": "f1", "type": "textarea", "label": "What it feels like:"}, {"id": "f2", "type": "textarea", "label": "The earliest sign I can catch:"}, {"id": "f3", "type": "textarea", "label": "What I will do when I notice it:"}]'::jsonb, array['anger management', 'regulation', 'self-monitoring', 'body awareness']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('anger-thought-check-record', 'Anger Thought Check Record', 'cbt'::resource_kind, 'A record of the thoughts under anger, such as "they did it on purpose," with a balanced version.', 'Use it to help a client examine the interpretations that fuel anger.', array['Adults']::text[], '20 minutes', 'Ask about the situation, the thought and the feeling. Look for other reasonable explanations without dismissing the client''s feelings. Practice the balanced thought aloud.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "What I told myself:"}, {"id": "f2", "type": "textarea", "label": "Another way to see it:"}, {"id": "f3", "type": "textarea", "label": "How I feel after considering it:"}]'::jsonb, array['anger management', 'thinking traps', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('anger-and-what-it-protects-values-page', 'Anger and What It Protects Values Page', 'act'::resource_kind, 'A page for noticing what matters to the client underneath their anger.', 'Use it to help a client link anger to the value it points to and choose how to act.', array['Adults']::text[], '25 minutes', 'Ask what the anger is trying to protect, such as fairness or respect. Then explore how they want to act on that value. Keep the focus on choices, not on suppressing anger.', '[{"id": "f0", "type": "textarea", "label": "A recent time I felt angry:"}, {"id": "f1", "type": "textarea", "label": "What I care about underneath it:"}, {"id": "f2", "type": "textarea", "label": "How I acted:"}, {"id": "f3", "type": "textarea", "label": "How I want to act the next time:"}]'::jsonb, array['anger management', 'values', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('doubt-dice-uncertainty-practice-game', 'Doubt Dice Uncertainty Practice Game', 'game'::resource_kind, 'A dice game where players practice leaving small uncertain moments unresolved.', 'Use it to help players practice sitting with small amounts of uncertainty.', array['Groups']::text[], '30 minutes', 'Roll for tiny uncertainty challenges such as leaving a card face down. Players rate discomfort before and after. Debrief what it was like to leave it alone. Use only with a client who is working with an exposure plan.', '[{"id": "f0", "type": "textarea", "label": "The challenge I rolled and my discomfort rating:"}, {"id": "f1", "type": "textarea", "label": "What happened when I left it alone?"}, {"id": "f2", "type": "textarea", "label": "What did I notice about the urge to check?"}, {"id": "f3", "type": "textarea", "label": "A tiny challenge I will try this week:"}]'::jsonb, array['OCD', 'game', 'exposure', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('ritual-wait-time-log', 'Ritual Wait Time Log', 'worksheet'::resource_kind, 'A log of urges to do a ritual, how long a delay lasted and what happened.', 'Use it to help a client notice what happens when they delay a ritual.', array['Adults']::text[], 'One week', 'Start with delays of one or two minutes so success is likely. Log what happens to the urge. Increase gradually with the client''s agreement and never push beyond their readiness.', '[{"id": "f0", "type": "textarea", "label": "The urge I noticed:"}, {"id": "f1", "type": "textarea", "label": "How long I delayed it:"}, {"id": "f2", "type": "textarea", "label": "What happened to the urge?"}, {"id": "f3", "type": "textarea", "label": "What I will try next time:"}]'::jsonb, array['OCD', 'exposure', 'self-monitoring']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('thought-is-not-fact-cards-for-intrusive-thoughts', 'Thought Is Not Fact Cards for Intrusive Thoughts', 'cbt'::resource_kind, 'Cards naming common intrusive thoughts with a reminder that having them is not acting on them.', 'Use it to help a client respond to an unwelcome thought as a thought.', array['Adults']::text[], '25 minutes', 'Have the client write their own intrusive thoughts on the cards. Pair each with a plain reminder that it is a thought. Practice reading them without trying to push them away.', '[{"id": "f0", "type": "textarea", "label": "An intrusive thought I have had:"}, {"id": "f1", "type": "textarea", "label": "What I tell myself about it:"}, {"id": "f2", "type": "textarea", "label": "A way to respond that is not a ritual:"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it?"}]'::jsonb, array['OCD', 'thinking traps', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('unwanted-thoughts-passing-like-clouds-practice', 'Unwanted Thoughts Passing Like Clouds Practice', 'act'::resource_kind, 'A page for noticing intrusive thoughts and letting them drift by while doing something that matters.', 'Use it to help a client carry intrusive thoughts while engaged in their day.', array['Adults']::text[], '20 minutes', 'Practice labeling a thought as "there is the thought" and returning to an activity. Do not use it as a way to get rid of thoughts. Invite honest notes on what is hard.', '[{"id": "f0", "type": "textarea", "label": "The thought and where I noticed it:"}, {"id": "f1", "type": "textarea", "label": "How I labeled it:"}, {"id": "f2", "type": "textarea", "label": "What I did next:"}, {"id": "f3", "type": "textarea", "label": "What I noticed in the days after:"}]'::jsonb, array['OCD', 'defusion', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('riding-out-doubt-distress-skills-plan', 'Riding Out Doubt Distress Skills Plan', 'dbt'::resource_kind, 'A plan for coping skills to use while resisting a ritual.', 'Use it to help a client prepare skills for the moments they choose not to ritualize.', array['Adults']::text[], '25 minutes', 'Choose two or three skills, such as paced breathing and a grounding task. Rehearse in session. Pair with the exposure plan the clinician has set up.', '[{"id": "f0", "type": "textarea", "label": "The ritual urge I am working on:"}, {"id": "f1", "type": "textarea", "label": "Skills I will use while I wait:"}, {"id": "f2", "type": "textarea", "label": "How I will remind myself why:"}, {"id": "f3", "type": "textarea", "label": "What helped most:"}]'::jsonb, array['OCD', 'distress tolerance', 'core DBT', 'exposure']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('surge-rise-and-fall-minute-chart', 'Surge Rise and Fall Minute Chart', 'worksheet'::resource_kind, 'A timeline for charting how a panic wave rises, peaks and falls.', 'Use it to help a client see that a surge of panic rises and passes.', array['Adults']::text[], '20 minutes', 'Have the client chart a recent wave minute by minute with a rating. Notice that the peak passes. Keep the focus on the pattern and what helped, not on analyzing the feelings.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I was doing:"}, {"id": "f1", "type": "textarea", "label": "My rating at each few minutes:"}, {"id": "f2", "type": "textarea", "label": "When did it peak?"}, {"id": "f3", "type": "textarea", "label": "What helped it ease?"}]'::jsonb, array['panic attacks', 'self-monitoring', 'exposure']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('sensation-two-readings-card-set', 'Sensation Two Readings Card Set', 'cbt'::resource_kind, 'Cards pairing a body sensation with a scary reading and a more balanced one.', 'Use it to help a client consider other explanations for body sensations.', array['Adults']::text[], '25 minutes', 'Ask the client to bring two or three sensations they fear. Write the scary and the balanced reading, noting that a medical check is for the client and their physician. Practice the balanced reading aloud.', '[{"id": "f0", "type": "textarea", "label": "A sensation I notice:"}, {"id": "f1", "type": "textarea", "label": "The scary meaning I give it:"}, {"id": "f2", "type": "textarea", "label": "Another possible meaning:"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself:"}]'::jsonb, array['panic attacks', 'thinking traps', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('making-room-for-the-wave-willingness-page', 'Making Room for the Wave Willingness Page', 'act'::resource_kind, 'A page for letting the sensations of panic be present while doing what matters.', 'Use it to help a client carry panic sensations while acting on a value.', array['Adults']::text[], '25 minutes', 'Describe the surge as something to make room for, not fight. Ask which value the client wants to move toward. Debrief what changed when they stopped fighting.', '[{"id": "f0", "type": "textarea", "label": "The sensations I notice:"}, {"id": "f1", "type": "textarea", "label": "What I usually do to stop them:"}, {"id": "f2", "type": "textarea", "label": "What I care about doing anyway:"}, {"id": "f3", "type": "textarea", "label": "What happened when I made room?"}]'::jsonb, array['panic attacks', 'willingness', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('slow-exhale-and-cold-pack-skill-plan', 'Slow Exhale and Cold Pack Skill Plan', 'dbt'::resource_kind, 'A plan for two body-based skills to use at the first signs of panic.', 'Use it to give a client two quick skills for high arousal.', array['Adults']::text[], '20 minutes', 'Practice paced breathing with longer exhales and a cool pack on the face in session, noting any health considerations first. The client chooses which fits. Keep it in a pocket card.', '[{"id": "f0", "type": "textarea", "label": "The first sign of panic I notice:"}, {"id": "f1", "type": "textarea", "label": "The skill I will use first:"}, {"id": "f2", "type": "textarea", "label": "How I felt before and after, from 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "Where I keep the card:"}]'::jsonb, array['panic attacks', 'distress tolerance', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('partner-coaching-during-a-panic-surge-plan', 'Partner Coaching During a Panic Surge Plan', 'couples'::resource_kind, 'A plan for how a partner can stay steady and helpful during a surge of panic.', 'Use it to help a partner know what to say and do when the other is panicking.', array['Couples']::text[], '25 minutes', 'Ask the person who panics to say what helps and what does not. The partner practices a short script and a calm tone. Rehearse it once in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps during a surge:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help:"}, {"id": "f2", "type": "textarea", "label": "Partner B: the words I will use:"}, {"id": "f3", "type": "textarea", "label": "How we will debrief afterward:"}]'::jsonb, array['panic attacks', 'support', 'coping skills', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('parent-pause-thought-check-sheet', 'Parent Pause Thought Check Sheet', 'cbt'::resource_kind, 'A sheet for catching the thought behind a parent''s strong reaction and trying a balanced one.', 'Use it to help a parent pause on the thought behind their reaction to a child.', array['Adults']::text[], '20 minutes', 'Ask for a specific moment and the thought that came up, such as "they are doing this on purpose." Explore other readings kindly, without blame. Practice a calmer line.', '[{"id": "f0", "type": "textarea", "label": "What my child did:"}, {"id": "f1", "type": "textarea", "label": "What I told myself it meant:"}, {"id": "f2", "type": "textarea", "label": "Another way to see it:"}, {"id": "f3", "type": "textarea", "label": "What I want to say or do instead:"}]'::jsonb, array['parenting', 'thinking traps', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('parenting-by-values-direction-page', 'Parenting by Values Direction Page', 'act'::resource_kind, 'A page for naming the parent a client wants to be and a small action that fits it today.', 'Use it to help a parent act on values in moments of stress.', array['Adults']::text[], '25 minutes', 'Ask what kind of parent they want their child to remember. Then pick one small action for this week. Treat slip-ups with kindness and curiosity.', '[{"id": "f0", "type": "textarea", "label": "What I want my child to feel around me:"}, {"id": "f1", "type": "textarea", "label": "A small action that fits this:"}, {"id": "f2", "type": "textarea", "label": "What gets in the way when I am stressed?"}, {"id": "f3", "type": "textarea", "label": "What I will try this week:"}]'::jsonb, array['parenting', 'values', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('parent-self-soothe-break-plan', 'Parent Self-Soothe Break Plan', 'dbt'::resource_kind, 'A plan for a short break to settle before responding to a child.', 'Use it to help a parent calm themselves before stepping back in.', array['Adults']::text[], '20 minutes', 'Plan a short break with a child-safe setup, such as telling the child "I need a minute." Choose a skill. Make sure the child is safe, and plan the return.', '[{"id": "f0", "type": "textarea", "label": "What my body does when I am overwhelmed:"}, {"id": "f1", "type": "textarea", "label": "What I will say to my child:"}, {"id": "f2", "type": "textarea", "label": "A skill I will use for a few minutes:"}, {"id": "f3", "type": "textarea", "label": "How I will come back and reconnect:"}]'::jsonb, array['parenting', 'coping skills', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('co-parent-team-meeting-agenda-sheet', 'Co-Parent Team Meeting Agenda Sheet', 'couples'::resource_kind, 'An agenda for co-parents to meet weekly on routines, rules and support.', 'Use it to help co-parents get on the same page and support each other.', array['Couples']::text[], '30 minutes', 'Keep it brief and kind: start with an appreciation, then pick one topic. Agree who does what. End on something positive.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciate about you as a parent:"}, {"id": "f1", "type": "textarea", "label": "Partner B: something I appreciate about you as a parent:"}, {"id": "f2", "type": "textarea", "label": "One thing we want to decide this week:"}, {"id": "f3", "type": "textarea", "label": "Who will do what?"}]'::jsonb, array['parenting', 'communication', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('family-feelings-check-in-wheel-craft', 'Family Feelings Check-In Wheel Craft', 'kids'::resource_kind, 'A family builds a spinner of feelings and uses it at dinner or bedtime.', 'Use it to help families share how everyone is feeling in a simple way.', array['Children']::text[], '40 minutes', 'Everyone helps make the wheel and takes turns spinning and sharing. The parent also shares their own and listens without fixing. Keep it short and fun.', '[{"id": "f0", "type": "textarea", "label": "Draw your favorite feeling on the wheel:"}, {"id": "f1", "type": "textarea", "label": "A feeling that was hard today:"}, {"id": "f2", "type": "textarea", "label": "What helps when I feel it?"}, {"id": "f3", "type": "textarea", "label": "What did parent share?"}]'::jsonb, array['parenting', 'children', 'emotion identification']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('values-while-everything-changes-page', 'Values While Everything Changes Page', 'act'::resource_kind, 'A page for new and expecting parents to name what matters and small ways to act on it.', 'Use it to help a client connect to values while life is being rearranged.', array['Adults']::text[], '25 minutes', 'Acknowledge how much is changing. Ask what matters most in this season and choose one small action. Keep the expectations gentle and let the client set them.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me in this season:"}, {"id": "f1", "type": "textarea", "label": "Something small that fits it:"}, {"id": "f2", "type": "textarea", "label": "What makes it hard right now?"}, {"id": "f3", "type": "textarea", "label": "What support could help?"}]'::jsonb, array['perinatal and postpartum', 'values', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('rest-and-nourish-self-care-skills-plan', 'Rest and Nourish Self-Care Skills Plan', 'dbt'::resource_kind, 'A plan for small acts of rest and care when time is short.', 'Use it to help a client plan small, doable acts of self-care.', array['Adults']::text[], '25 minutes', 'Look for tiny pieces of time and for who can help. Use a skill like building mastery or accumulating positive emotions. Check in on what feels possible this week and revise it.', '[{"id": "f0", "type": "textarea", "label": "What my days look like now:"}, {"id": "f1", "type": "textarea", "label": "Small acts of rest I could fit in:"}, {"id": "f2", "type": "textarea", "label": "Who could help me with this?"}, {"id": "f3", "type": "textarea", "label": "What I will try this week:"}]'::jsonb, array['perinatal and postpartum', 'coping skills', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('new-baby-partner-teamwork-planner', 'New Baby Partner Teamwork Planner', 'couples'::resource_kind, 'A planner for dividing night and daytime care, rest and time together.', 'Use it to help new parents plan teamwork and protect rest.', array['Couples']::text[], '30 minutes', 'Look at the whole day and night and divide tasks so both can rest. Plan one short moment of connection daily. Review weekly as the baby grows.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I can take on:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can take on:"}, {"id": "f2", "type": "textarea", "label": "How we will protect rest for both of us:"}, {"id": "f3", "type": "textarea", "label": "A small way to connect each day:"}]'::jsonb, array['perinatal and postpartum', 'planning', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('becoming-a-big-sibling-story-book', 'Becoming a Big Sibling Story Book', 'kids'::resource_kind, 'A child builds a small book about a baby coming and what stays the same.', 'Use it to help an older child talk about a new baby arriving.', array['Children']::text[], '40 minutes', 'The child draws pictures of what changes and what stays the same. The parent adds special time just for the older child. Listen to mixed feelings without correcting them.', '[{"id": "f0", "type": "textarea", "label": "Draw what I am excited about:"}, {"id": "f1", "type": "textarea", "label": "Draw something that is hard:"}, {"id": "f2", "type": "textarea", "label": "What stays the same?"}, {"id": "f3", "type": "textarea", "label": "What special time will parent plan with me?"}]'::jsonb, array['perinatal and postpartum', 'children', 'art']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('parenting-support-circle-conversation-game', 'Parenting Support Circle Conversation Game', 'game'::resource_kind, 'A group game with prompt cards that invite new parents to share and support each other.', 'Use it to help new parents connect and feel less alone.', array['Groups']::text[], '40 minutes', 'Pass a card around with prompts like a small win or a hard moment. Players may pass on any card. Debrief what they heard that was helpful.', '[{"id": "f0", "type": "textarea", "label": "A card I answered and what I shared:"}, {"id": "f1", "type": "textarea", "label": "Something I heard that helped:"}, {"id": "f2", "type": "textarea", "label": "A small win from this week:"}, {"id": "f3", "type": "textarea", "label": "Someone I can reach out to:"}]'::jsonb, array['perinatal and postpartum', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('build-mastery-small-skill-ladder', 'Build Mastery Small Skill Ladder', 'dbt'::resource_kind, 'A ladder of small tasks that build a client''s sense of capability.', 'Use it to help a client build a sense of competence through small steps.', array['Adults']::text[], '25 minutes', 'Choose something just challenging enough, such as a new recipe. Break it into steps and notice each completed one. Celebrate and move to the next rung.', '[{"id": "f0", "type": "textarea", "label": "A skill I want to build:"}, {"id": "f1", "type": "textarea", "label": "The steps on my ladder:"}, {"id": "f2", "type": "textarea", "label": "The step I did this week:"}, {"id": "f3", "type": "textarea", "label": "How it felt to do it:"}]'::jsonb, array['self-esteem', 'core DBT', 'strengths']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('seeing-the-best-in-each-other-exchange', 'Seeing the Best in Each Other Exchange', 'couples'::resource_kind, 'An exchange where partners write what they admire and read it aloud.', 'Use it to help partners hear what they value in each other.', array['Couples']::text[], '25 minutes', 'Each partner writes specific things they admire. Reading aloud can feel vulnerable, so slow down. Ask the listener to just take it in.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I admire in you:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I admire in you:"}, {"id": "f2", "type": "textarea", "label": "What was it like to hear this?"}, {"id": "f3", "type": "textarea", "label": "What will we do to keep noticing?"}]'::jsonb, array['self-esteem', 'connection', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('things-that-make-me-me-box-craft', 'Things That Make Me Me Box Craft', 'kids'::resource_kind, 'Children decorate a box and fill it with things that show who they are.', 'Use it to help a child see and celebrate what makes them who they are.', array['Children']::text[], '45 minutes', 'The child chooses drawings, objects or notes. The parent adds a note about something they love about the child. Look through the box together at tough moments.', '[{"id": "f0", "type": "textarea", "label": "Draw something you are good at:"}, {"id": "f1", "type": "textarea", "label": "Something kind you did:"}, {"id": "f2", "type": "textarea", "label": "What makes you you?"}, {"id": "f3", "type": "textarea", "label": "What note did parent add?"}]'::jsonb, array['self-esteem', 'children', 'art']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('compliment-catch-circle-game', 'Compliment Catch Circle Game', 'game'::resource_kind, 'A group game of tossing a ball and naming a strength about the catcher.', 'Use it to help a group give and receive specific, genuine strengths.', array['Groups']::text[], '25 minutes', 'Players toss a ball and say one real strength about the catcher. Catchers practice saying thank you. Debrief what was hard to hear.', '[{"id": "f0", "type": "textarea", "label": "A strength I heard about me:"}, {"id": "f1", "type": "textarea", "label": "A strength I gave to someone:"}, {"id": "f2", "type": "textarea", "label": "What was hard about accepting it?"}, {"id": "f3", "type": "textarea", "label": "Something I will remember:"}]'::jsonb, array['self-esteem', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('inner-critic-and-inner-coach-two-voice-page', 'Inner Critic and Inner Coach Two-Voice Page', 'worksheet'::resource_kind, 'A two-column page where a client writes the critic''s lines and a coach''s reply.', 'Use it to help a client practice answering their inner critic with a fairer voice.', array['Adults']::text[], '20 minutes', 'Have the client write what the critic says in its own words. Then draft a coach reply that is honest and kind. Practice saying it aloud.', '[{"id": "f0", "type": "textarea", "label": "The critic says:"}, {"id": "f1", "type": "textarea", "label": "The coach replies:"}, {"id": "f2", "type": "textarea", "label": "Which voice do I believe more right now?"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself next time:"}]'::jsonb, array['self-esteem', 'self-compassion']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('partner-practice-partner-for-social-plans', 'Partner Practice Partner for Social Plans', 'couples'::resource_kind, 'A plan for a partner to support a gradual approach to social situations.', 'Use it to help partners plan social outings at a pace that works.', array['Couples']::text[], '25 minutes', 'Choose one outing and agree on a signal and an exit plan. The partner supports without pushing. Debrief what went well afterward.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the outing and what worries me:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need from you:"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I can support:"}, {"id": "f3", "type": "textarea", "label": "Our signal and exit plan:"}]'::jsonb, array['social anxiety', 'support', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('shy-superhero-mask-and-power-page', 'Shy Superhero Mask and Power Page', 'kids'::resource_kind, 'Children design a superhero whose power is a quiet strength and plan one brave step.', 'Use it to help a shy child find strengths and take small social steps.', array['Children']::text[], '30 minutes', 'The child designs a hero and a power such as listening. Together choose a tiny step, such as saying hi. Parent cheers on effort, not results.', '[{"id": "f0", "type": "textarea", "label": "Draw your superhero:"}, {"id": "f1", "type": "textarea", "label": "Their quiet power:"}, {"id": "f2", "type": "textarea", "label": "One tiny brave step I will take:"}, {"id": "f3", "type": "textarea", "label": "What parent will do to help:"}]'::jsonb, array['social anxiety', 'children', 'strengths']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('chat-starter-pair-cards-game', 'Chat Starter Pair Cards Game', 'game'::resource_kind, 'A game with cards for starting, keeping and ending a short chat.', 'Use it to give a group a low-stakes place to practice small talk.', array['Groups']::text[], '30 minutes', 'Pairs draw cards such as a question to open a chat. Rotate partners. Debrief what felt easier than expected and what to try next.', '[{"id": "f0", "type": "textarea", "label": "The card I drew:"}, {"id": "f1", "type": "textarea", "label": "What I said and how it felt:"}, {"id": "f2", "type": "textarea", "label": "What surprised me?"}, {"id": "f3", "type": "textarea", "label": "A small chat I will try this week:"}]'::jsonb, array['social anxiety', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('social-ladder-steps-planner', 'Social Ladder Steps Planner', 'worksheet'::resource_kind, 'A ladder of social steps ordered by difficulty with a place to log each try.', 'Use it to help a client plan small social steps in a gradual order.', array['Adults']::text[], '30 minutes', 'Build the ladder together, starting with steps that feel only mildly hard. Log predictions and results. Move up only when the client feels ready.', '[{"id": "f0", "type": "textarea", "label": "The steps on my ladder, easiest first:"}, {"id": "f1", "type": "textarea", "label": "The one I will try:"}, {"id": "f2", "type": "textarea", "label": "My prediction and what happened:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['social anxiety', 'exposure', 'planning']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('spotlight-effect-check-record', 'Spotlight Effect Check Record', 'cbt'::resource_kind, 'A record for testing the belief that everyone is watching and judging.', 'Use it to help a client test how much attention others actually give.', array['Adults']::text[], '25 minutes', 'Have the client predict how much others noticed, then check by observation. Compare to reality. Keep it a curious experiment.', '[{"id": "f0", "type": "textarea", "label": "The situation and what I feared people noticed:"}, {"id": "f1", "type": "textarea", "label": "What I predicted:"}, {"id": "f2", "type": "textarea", "label": "What I actually saw:"}, {"id": "f3", "type": "textarea", "label": "What I make of that:"}]'::jsonb, array['social anxiety', 'thinking traps', 'behavioral experiment']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('memory-jar-craft-for-missing-someone', 'Memory Jar Craft for Missing Someone', 'kids'::resource_kind, 'Children decorate a jar and fill it with drawings and notes about someone they miss.', 'Use it to give a grieving child a way to keep memories close.', array['Children']::text[], '40 minutes', 'The child chooses what goes in the jar. The parent shares a memory too and answers questions honestly in simple words. Let the child decide when to open it.', '[{"id": "f0", "type": "textarea", "label": "Draw a happy memory:"}, {"id": "f1", "type": "textarea", "label": "What I miss:"}, {"id": "f2", "type": "textarea", "label": "What I want to tell them:"}, {"id": "f3", "type": "textarea", "label": "What parent shared with me:"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('remembering-together-memory-circle-game', 'Remembering Together Memory Circle Game', 'game'::resource_kind, 'A group game of passing a candle or object and sharing a memory.', 'Use it to help a group share memories of those they have lost.', array['Groups']::text[], '40 minutes', 'Players pass an object and may share or pass. Hold the space gently for tears and silence. Debrief how it felt and how to care for themselves afterward.', '[{"id": "f0", "type": "textarea", "label": "A memory I shared or kept in mind:"}, {"id": "f1", "type": "textarea", "label": "What it felt like:"}, {"id": "f2", "type": "textarea", "label": "What I need after tonight:"}, {"id": "f3", "type": "textarea", "label": "Who I can reach out to?"}]'::jsonb, array['grief and loss', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('grief-wave-pattern-notes', 'Grief Wave Pattern Notes', 'worksheet'::resource_kind, 'A tracker for when waves of grief come, what sets them off and what helps.', 'Use it to help a client notice the pattern of grief waves and what supports them.', array['Adults']::text[], 'One week', 'Reassure that waves vary and there is no right way to grieve. Look for triggers and comforts. Note anniversaries coming up and plan support.', '[{"id": "f0", "type": "textarea", "label": "When a wave came:"}, {"id": "f1", "type": "textarea", "label": "What set it off:"}, {"id": "f2", "type": "textarea", "label": "What helped:"}, {"id": "f3", "type": "textarea", "label": "What I need this week:"}]'::jsonb, array['grief and loss', 'self-monitoring', 'support']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('should-have-thoughts-balanced-reply-sheet', 'Should Have Thoughts Balanced Reply Sheet', 'cbt'::resource_kind, 'A sheet for the "if only" thoughts that follow a loss and a kinder reply.', 'Use it to help a client respond kindly to guilt-laden thoughts after a loss.', array['Adults']::text[], '25 minutes', 'Let the client voice the thoughts without rushing to fix. Consider what they knew then versus now. Offer a kinder statement together.', '[{"id": "f0", "type": "textarea", "label": "The \"if only\" thought:"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time:"}, {"id": "f2", "type": "textarea", "label": "What I would tell a friend:"}, {"id": "f3", "type": "textarea", "label": "A kinder thing to tell myself:"}]'::jsonb, array['grief and loss', 'thinking traps', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('love-and-loss-side-by-side-page', 'Love and Loss Side by Side Page', 'act'::resource_kind, 'A page for holding grief and the love beneath it while still choosing small steps in life.', 'Use it to help a client carry grief alongside what matters to them.', array['Adults']::text[], '25 minutes', 'Grief is the other side of love; invite them to say what they loved. Choose a small step. Do not push toward closure.', '[{"id": "f0", "type": "textarea", "label": "Who or what I am grieving:"}, {"id": "f1", "type": "textarea", "label": "What I love or valued about them:"}, {"id": "f2", "type": "textarea", "label": "A small way to honor it:"}, {"id": "f3", "type": "textarea", "label": "A small step in my own life:"}]'::jsonb, array['grief and loss', 'values', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('repair-phrases-role-play-game', 'Repair Phrases Role Play Game', 'game'::resource_kind, 'A game where partners or friends draw a conflict and practice a repair phrase.', 'Use it to help players practice apologies and repair after a disagreement.', array['Groups']::text[], '30 minutes', 'Players draw a scenario and practice a repair phrase such as "I can see how that hurt." Debrief what felt sincere. Keep scenarios mild.', '[{"id": "f0", "type": "textarea", "label": "The scenario and the phrase I tried:"}, {"id": "f1", "type": "textarea", "label": "What felt sincere?"}, {"id": "f2", "type": "textarea", "label": "What I would add:"}, {"id": "f3", "type": "textarea", "label": "A repair I want to make:"}]'::jsonb, array['relationship issues', 'game', 'communication']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('relationship-needs-and-requests-sheet', 'Relationship Needs and Requests Sheet', 'worksheet'::resource_kind, 'A sheet for turning a complaint into a need and a specific request.', 'Use it to help a client turn frustration into a clear request.', array['Adults']::text[], '20 minutes', 'Move from "you never" to a feeling, a need and a doable request. Practice the wording aloud. Test it with a real request this week.', '[{"id": "f0", "type": "textarea", "label": "A complaint I have:"}, {"id": "f1", "type": "textarea", "label": "The need underneath:"}, {"id": "f2", "type": "textarea", "label": "A specific request I could make:"}, {"id": "f3", "type": "textarea", "label": "How I will say it:"}]'::jsonb, array['relationship issues', 'communication']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('mind-reading-check-in-relationships-record', 'Mind Reading Check in Relationships Record', 'cbt'::resource_kind, 'A record for testing assumptions about what a partner or friend thinks.', 'Use it to help a client check assumptions about what others think.', array['Adults']::text[], '20 minutes', 'Have the client list the assumption and alternatives, then plan a way to check it by asking. Debrief what they learned.', '[{"id": "f0", "type": "textarea", "label": "What I assumed they thought:"}, {"id": "f1", "type": "textarea", "label": "Other possible explanations:"}, {"id": "f2", "type": "textarea", "label": "How I could check:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['relationship issues', 'thinking traps', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('showing-up-in-relationships-by-values-page', 'Showing Up in Relationships by Values Page', 'act'::resource_kind, 'A page for naming the partner or friend a client wants to be and one action to match.', 'Use it to help a client act on values within a relationship.', array['Adults']::text[], '25 minutes', 'Ask what kind of presence they want to be with this person. Pick one small action they can take this week. Notice what pulls them away from it, and talk about it kindly.', '[{"id": "f0", "type": "textarea", "label": "The kind of partner or friend I want to be:"}, {"id": "f1", "type": "textarea", "label": "One action that fits:"}, {"id": "f2", "type": "textarea", "label": "What pulls me off course:"}, {"id": "f3", "type": "textarea", "label": "When I will do it:"}]'::jsonb, array['relationship issues', 'values', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('give-skill-conversation-practice-sheet', 'GIVE Skill Conversation Practice Sheet', 'dbt'::resource_kind, 'A sheet for practicing gentle, interested, validating and easy manner in a conversation.', 'Use it to help a client keep a relationship strong while asking for something.', array['Adults']::text[], '25 minutes', 'Walk through each letter with a real conversation. Role-play once in session. Ask which letter is hardest.', '[{"id": "f0", "type": "textarea", "label": "The conversation I plan to have:"}, {"id": "f1", "type": "textarea", "label": "How I will be gentle and interested:"}, {"id": "f2", "type": "textarea", "label": "How I will validate the other person:"}, {"id": "f3", "type": "textarea", "label": "What I will keep easy in my manner:"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('trusted-people-and-safe-places-map', 'Trusted People and Safe Places Map', 'worksheet'::resource_kind, 'A map of people, places and activities that feel safe and supportive to a client now.', 'Use it to help a client see the sources of safety and support around them today.', array['Adults']::text[], '25 minutes', 'Stay in the present: who and where feels safe now. Let the client decide what to include and how much. Never ask for details of what happened. If distress rises, pause and ground together. Share 988 (call or text) if the client is ever in crisis.', '[{"id": "f0", "type": "textarea", "label": "People who feel safe to me now:"}, {"id": "f1", "type": "textarea", "label": "Places that feel safe:"}, {"id": "f2", "type": "textarea", "label": "Things I do that help me feel calm:"}, {"id": "f3", "type": "textarea", "label": "Who I could reach out to, and 988 (call or text) if I am in crisis:"}]'::jsonb, array['sexual abuse', 'safety', 'support', 'grounding']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('self-blame-thought-gentle-check-sheet', 'Self-Blame Thought Gentle Check Sheet', 'cbt'::resource_kind, 'A sheet for noticing self-blaming thoughts in the present and a kinder reply, without recounting events.', 'Use it to help a client respond to self-blame with compassion in the present.', array['Adults']::text[], '25 minutes', 'Work only with the thought as it shows up now. Never ask the client to write or describe what happened. Offer a kinder statement and emphasize that responsibility lies with the person who harmed them. Close with grounding.', '[{"id": "f0", "type": "textarea", "label": "A self-blaming thought that shows up:"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend who thought this:"}, {"id": "f2", "type": "textarea", "label": "A kinder thing I can tell myself:"}, {"id": "f3", "type": "textarea", "label": "What helps me feel steady afterward:"}]'::jsonb, array['sexual abuse', 'self-compassion', 'core CBT', 'safety']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('reclaiming-life-direction-values-page', 'Reclaiming Life Direction Values Page', 'act'::resource_kind, 'A page for naming what a client wants to build in their life, at a pace they choose.', 'Use it to help a client reconnect with what they want to move toward.', array['Adults']::text[], '30 minutes', 'Keep the focus on today and what comes next. Let the client name one value and one small step, and respect any pause. Never request details. Check how it felt afterward.', '[{"id": "f0", "type": "textarea", "label": "Something I want more of in my life:"}, {"id": "f1", "type": "textarea", "label": "One small step toward it:"}, {"id": "f2", "type": "textarea", "label": "What I need in order to feel safe doing it:"}, {"id": "f3", "type": "textarea", "label": "Who can support me?"}]'::jsonb, array['sexual abuse', 'values', 'committed action', 'pacing']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-calm-toolbox-builder', 'Distress Tolerance Calm Toolbox Builder', 'dbt'::resource_kind, 'A page for building a toolbox of calming skills a client can reach for when overwhelmed.', 'Use it to help a client gather skills that help them settle in the present.', array['Adults']::text[], '30 minutes', 'Have the client choose skills from several categories and try each briefly. The toolbox is about settling now and not about discussing the past. Revisit as needs change. Name 988 (call or text) as a support.', '[{"id": "f0", "type": "textarea", "label": "Skills that calm my body:"}, {"id": "f1", "type": "textarea", "label": "Skills that shift my attention:"}, {"id": "f2", "type": "textarea", "label": "Things that comfort me:"}, {"id": "f3", "type": "textarea", "label": "Where I keep my toolbox, and 988 (call or text) if I need immediate help:"}]'::jsonb, array['sexual abuse', 'distress tolerance', 'core DBT', 'grounding']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('my-safe-people-hand-drawing-activity', 'My Safe People Hand Drawing Activity', 'kids'::resource_kind, 'A child traces a hand and writes a trusted adult on each finger.', 'Use it to help a child name the grown-ups they can go to when something feels wrong.', array['Children']::text[], '25 minutes', 'The child traces a hand and draws or names one safe person per finger. The parent or clinician confirms those adults. Remind yourself of your reporting duties if a child discloses, and respond calmly and believe the child.', '[{"id": "f0", "type": "textarea", "label": "Trace your hand and name five safe people:"}, {"id": "f1", "type": "textarea", "label": "What makes each one safe?"}, {"id": "f2", "type": "textarea", "label": "How I can tell someone if something feels wrong:"}, {"id": "f3", "type": "textarea", "label": "What parent will do if I tell them:"}]'::jsonb, array['sexual abuse', 'children', 'safety', 'support']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('coping-skill-match-experiment-log', 'Coping Skill Match Experiment Log', 'cbt'::resource_kind, 'A log for trying a skill, rating mood before and after, and learning what fits which feeling.', 'Use it to help a client learn which skill fits which situation.', array['Adults']::text[], 'One week', 'Keep it practical: try one skill per entry and rate before and after. Look for patterns together. Some will not help, which is useful information.', '[{"id": "f0", "type": "textarea", "label": "The situation and my feeling:"}, {"id": "f1", "type": "textarea", "label": "The skill I tried:"}, {"id": "f2", "type": "textarea", "label": "My rating before and after:"}, {"id": "f3", "type": "textarea", "label": "What I will use next time:"}]'::jsonb, array['coping skills', 'self-monitoring', 'core CBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('away-or-toward-fork-page', 'Away or Toward Fork Page', 'act'::resource_kind, 'A page for noticing a hard moment and choosing between moving away from or toward what matters.', 'Use it to help a client choose actions that serve values in hard moments.', array['Adults']::text[], '25 minutes', 'Draw a fork: away moves versus toward moves. Ask for a recent example. Notice what hooked them and what they could do next time.', '[{"id": "f0", "type": "textarea", "label": "The hard moment:"}, {"id": "f1", "type": "textarea", "label": "What hooked me:"}, {"id": "f2", "type": "textarea", "label": "An away move I made:"}, {"id": "f3", "type": "textarea", "label": "A toward move I could make:"}]'::jsonb, array['coping skills', 'values', 'core ACT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('accepts-distraction-menu-page', 'ACCEPTS Distraction Menu Page', 'dbt'::resource_kind, 'A menu of distraction skills for getting through a spike of distress.', 'Use it to help a client choose a distraction while a feeling passes.', array['Adults']::text[], '25 minutes', 'Go through the ACCEPTS list and try a few. Have them mark which they would use. Distraction is for getting through, then returning to problem solving.', '[{"id": "f0", "type": "textarea", "label": "The spike of distress I am planning for:"}, {"id": "f1", "type": "textarea", "label": "Distractions I will use:"}, {"id": "f2", "type": "textarea", "label": "How long I will use them:"}, {"id": "f3", "type": "textarea", "label": "What I will do afterward:"}]'::jsonb, array['coping skills', 'distress tolerance', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('coping-together-calm-pair-plan', 'Coping Together Calm Pair Plan', 'couples'::resource_kind, 'A plan for partners to cope together when stress is high and to cool down apart when needed.', 'Use it to help partners pick shared and separate coping skills.', array['Couples']::text[], '25 minutes', 'Each partner names what helps them calm. Agree on a signal for a break and a time to return. Practice a break once in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me cool down:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what helps me cool down:"}, {"id": "f2", "type": "textarea", "label": "Our break signal and return time:"}, {"id": "f3", "type": "textarea", "label": "Something calming we can do together:"}]'::jsonb, array['coping skills', 'communication', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('coping-skills-treasure-hunt-game', 'Coping Skills Treasure Hunt Game', 'kids'::resource_kind, 'A treasure hunt where each clue leads to a coping skill to try.', 'Use it to help a child try and choose coping skills while having fun.', array['Children']::text[], '35 minutes', 'Hide cards around the room, each with a skill like belly breathing. The child tries each and picks favorites. The parent joins in and notes which helped.', '[{"id": "f0", "type": "textarea", "label": "The skills I found:"}, {"id": "f1", "type": "textarea", "label": "My favorite one:"}, {"id": "f2", "type": "textarea", "label": "When I could use it:"}, {"id": "f3", "type": "textarea", "label": "What parent noticed:"}]'::jsonb, array['coping skills', 'children', 'play']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('fear-and-values-willingness-page', 'Fear and Values Willingness Page', 'act'::resource_kind, 'A page for naming what a fear gets in the way of and one small step toward it.', 'Use it to help a client link small steps with a fear to what they care about.', array['Adults']::text[], '25 minutes', 'Ask what life the fear is limiting. Choose a small step that fits the plan and the client''s readiness. Notice willingness, not perfect calm.', '[{"id": "f0", "type": "textarea", "label": "What I am afraid of:"}, {"id": "f1", "type": "textarea", "label": "What it keeps me from:"}, {"id": "f2", "type": "textarea", "label": "One small step I am willing to take:"}, {"id": "f3", "type": "textarea", "label": "What I noticed:"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('fear-ladder-skills-support-plan', 'Fear Ladder Skills Support Plan', 'dbt'::resource_kind, 'A plan for the skills a client will use while climbing a fear ladder.', 'Use it to help a client prepare coping skills for each step of a gradual plan.', array['Adults']::text[], '30 minutes', 'Pair each step with a skill like paced breathing. Rehearse in session. Pace according to the client''s readiness.', '[{"id": "f0", "type": "textarea", "label": "The next step on my ladder:"}, {"id": "f1", "type": "textarea", "label": "Skills I will use:"}, {"id": "f2", "type": "textarea", "label": "How I will know I am ready:"}, {"id": "f3", "type": "textarea", "label": "What I will do afterward:"}]'::jsonb, array['phobias', 'core DBT', 'exposure']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('supporting-a-partner-with-a-fear-guide', 'Supporting a Partner With a Fear Guide', 'couples'::resource_kind, 'A guide for partners on supporting gradual steps without pushing or covering for the fear.', 'Use it to help a partner support steps toward a feared situation.', array['Couples']::text[], '25 minutes', 'The person with the fear says what helps and what pushes too hard. The partner learns to encourage without rescuing. Practice an encouraging line.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a fear I am working on:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what helps and what does not:"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I will support:"}, {"id": "f3", "type": "textarea", "label": "How we will celebrate steps:"}]'::jsonb, array['phobias', 'support', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('brave-staircase-drawing-page', 'Brave Staircase Drawing Page', 'kids'::resource_kind, 'A child draws a staircase of steps toward a feared thing and colors each as tried.', 'Use it to help a child see a fear as a series of small steps.', array['Children']::text[], '30 minutes', 'The child draws stairs and names each step, from smallest to biggest. The parent cheers on each try and does not push. Revisit weekly.', '[{"id": "f0", "type": "textarea", "label": "Draw your staircase and label each step:"}, {"id": "f1", "type": "textarea", "label": "The step I will try next:"}, {"id": "f2", "type": "textarea", "label": "What helps me feel brave?"}, {"id": "f3", "type": "textarea", "label": "What did parent do to help?"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('face-the-fear-safe-game-night', 'Face the Fear Safe Game Night', 'game'::resource_kind, 'A group game where players challenge each other to small, agreed-upon braver steps.', 'Use it to help a group practice small steps with a fear in a supportive setting.', array['Groups']::text[], '35 minutes', 'Each player picks a small, agreed step. The group cheers and no one is pushed. Debrief what helped them try.', '[{"id": "f0", "type": "textarea", "label": "The step I chose and tried:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body:"}, {"id": "f2", "type": "textarea", "label": "What helped me try it?"}, {"id": "f3", "type": "textarea", "label": "The next step I want to take:"}]'::jsonb, array['phobias', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('mindful-body-appreciation-skills-page', 'Mindful Body Appreciation Skills Page', 'dbt'::resource_kind, 'A page for noticing what the body does with curiosity and without judgment.', 'Use it to help a client appreciate what their body does and notice it with kindness.', array['Adults']::text[], '20 minutes', 'Guide a short mindful moment that notices what the body does, such as walking or hugging. Avoid anything about size or shape. Invite curiosity and gratitude.', '[{"id": "f0", "type": "textarea", "label": "Something my body did today:"}, {"id": "f1", "type": "textarea", "label": "How I noticed it without judging:"}, {"id": "f2", "type": "textarea", "label": "A word of thanks to my body:"}, {"id": "f3", "type": "textarea", "label": "How I will notice this again:"}]'::jsonb, array['body image', 'mindfulness', 'core DBT']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('affirming-each-other-beyond-looks-exchange', 'Affirming Each Other Beyond Looks Exchange', 'couples'::resource_kind, 'An exchange where partners name what they value about each other apart from appearance.', 'Use it to help partners appreciate each other''s character and presence.', array['Couples']::text[], '25 minutes', 'Each partner names qualities such as humor and kindness. Avoid comments about appearance. Debrief what it felt like to hear.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I value in you:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I value in you:"}, {"id": "f2", "type": "textarea", "label": "What was it like to hear this?"}, {"id": "f3", "type": "textarea", "label": "How we will keep noticing it:"}]'::jsonb, array['body image', 'connection', 'couples']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('my-body-helps-me-superhero-drawing', 'My Body Helps Me Superhero Drawing', 'kids'::resource_kind, 'Children draw themselves as heroes with powers their body gives them.', 'Use it to help a child notice what their body helps them do.', array['Children']::text[], '30 minutes', 'The child draws a hero self with powers like running, hugging and dancing. The parent adds a thank you. Keep comments off appearance.', '[{"id": "f0", "type": "textarea", "label": "Draw your hero self:"}, {"id": "f1", "type": "textarea", "label": "A power my body gives me:"}, {"id": "f2", "type": "textarea", "label": "Something I love to do with my body:"}, {"id": "f3", "type": "textarea", "label": "What parent said about my powers:"}]'::jsonb, array['body image', 'children', 'strengths']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('feel-good-strengths-circle-game-for-teens', 'Feel-Good Strengths Circle Game for Teens', 'game'::resource_kind, 'A group game of naming a quality, skill or action that is not about looks.', 'Use it to help teens value what they do and who they are.', array['Groups']::text[], '30 minutes', 'Players pass a card prompt such as a skill they are proud of. Keep appearance off the table. Debrief what it felt like to focus on what they do.', '[{"id": "f0", "type": "textarea", "label": "A skill or quality I named:"}, {"id": "f1", "type": "textarea", "label": "One I heard from someone else:"}, {"id": "f2", "type": "textarea", "label": "How focusing on this felt:"}, {"id": "f3", "type": "textarea", "label": "What I will keep noticing:"}]'::jsonb, array['body image', 'game', 'group']::text[], '2026-11-09T15:00:00+00:00'::timestamptz),
  ('media-and-comparison-awareness-log', 'Media and Comparison Awareness Log', 'worksheet'::resource_kind, 'A log for noticing when media prompts comparison and what a client does next.', 'Use it to help a client notice the moments when comparison creeps in and choose a response.', array['Adults']::text[], 'One week', 'Have the client log moments of comparison and what they told themselves. Look for patterns, such as certain apps. Choose one small change, like muting an account.', '[{"id": "f0", "type": "textarea", "label": "Where I noticed comparing:"}, {"id": "f1", "type": "textarea", "label": "What I told myself:"}, {"id": "f2", "type": "textarea", "label": "What I did next:"}, {"id": "f3", "type": "textarea", "label": "One small change I can try:"}]'::jsonb, array['body image', 'self-monitoring', 'thinking traps']::text[], '2026-11-09T15:00:00+00:00'::timestamptz)
insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('parent-routine-builder', 'Parent Routine Builder', 'worksheet'::resource_kind, 'A page for building morning and bedtime routines with the child''s input.', 'Use it to help a parent set up predictable routines the child helps shape.', array['Adults']::text[], '30 minutes', 'Walk through the morning and bedtime with the parent. List steps, then ask the child to add ideas. Use visual charts for young children. Start with one routine and expand later. Keep tone warm, not rigid.', '[{"id": "f0", "type": "textarea", "label": "Our morning steps"}, {"id": "f1", "type": "textarea", "label": "Our bedtime steps"}, {"id": "f2", "type": "textarea", "label": "What my child wants to add"}, {"id": "f3", "type": "textarea", "label": "Where we get stuck"}, {"id": "f4", "type": "textarea", "label": "A visual cue I will use"}, {"id": "f5", "type": "textarea", "label": "How I will praise effort"}]'::jsonb, array['parenting', 'routines', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('praise-jar-family-craft', 'Praise Jar Family Craft', 'kids'::resource_kind, 'A jar the family fills with notes of things that went well.', 'Use it to help a family notice and name effort.', array['Children']::text[], '25 minutes', 'The child decorates a jar and the parent writes or draws notes of effort. Read a few notes at dinner or bedtime. Tell the parent to praise specific actions. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw our jar"}, {"id": "f1", "type": "textarea", "label": "A note about something I did well"}, {"id": "f2", "type": "textarea", "label": "A note about my grown-up"}, {"id": "f3", "type": "textarea", "label": "How I felt reading notes"}, {"id": "f4", "type": "textarea", "label": "When we will read them"}]'::jsonb, array['parenting', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('calm-response-role-play-game', 'Calm Response Role Play Game', 'game'::resource_kind, 'Parents take turns drawing scenarios and practicing a calm response.', 'Use it to help parents rehearse calm replies to tough moments.', array['Adults', 'Groups']::text[], '35 minutes', 'Make cards of common moments like refusing homework. Parents take turns playing the child and the parent. Others give feedback on what worked. Debrief on what made calm hard and what helps. Allow passing.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "My calm response"}, {"id": "f2", "type": "textarea", "label": "What the group said helped"}, {"id": "f3", "type": "textarea", "label": "What was hardest"}, {"id": "f4", "type": "textarea", "label": "What I will try at home"}]'::jsonb, array['parenting', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('co-parent-alignment-conversation-sheet', 'Co-Parent Alignment Conversation Sheet', 'couples'::resource_kind, 'A sheet for co-parents to talk about rules, roles and support.', 'Use it to help co-parents get on the same page and support each other.', array['Couples']::text[], '40 minutes', 'Each parent lists the top three rules they care about. Compare lists and discuss where they differ with curiosity. Agree on a short plan and how to back each other up in front of the child. Raise only issues that are safe to discuss together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the three rules I care about most"}, {"id": "f1", "type": "textarea", "label": "Partner B: the three rules I care about most"}, {"id": "f2", "type": "textarea", "label": "Where we differ"}, {"id": "f3", "type": "textarea", "label": "What we agree on"}, {"id": "f4", "type": "textarea", "label": "How we back each other up"}, {"id": "f5", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['parenting', 'couples', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('validation-phrases-for-parents-practice', 'Validation Phrases for Parents Practice', 'dbt'::resource_kind, 'A practice sheet for validating a child''s feelings before problem solving.', 'Use it to help parents practice validating phrases.', array['Adults']::text[], '25 minutes', 'Share a short list of validating phrases and practice with real examples. Distinguish validation from agreeing or giving in. Have the parent role-play with you, then try it once at home.', '[{"id": "f0", "type": "textarea", "label": "A time my child was upset"}, {"id": "f1", "type": "textarea", "label": "What I usually say"}, {"id": "f2", "type": "textarea", "label": "A validating phrase I could use"}, {"id": "f3", "type": "textarea", "label": "What I want to do after validating"}, {"id": "f4", "type": "textarea", "label": "How it went when I tried"}]'::jsonb, array['parenting', 'core DBT', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('night-shift-sharing-and-rest-block-planner', 'Night Shift Sharing and Rest Block Planner', 'worksheet'::resource_kind, 'A planner for dividing nights and daytime rest among people who can help.', 'Use it to help a new parent find protected rest and support.', array['Adults', 'Couples']::text[], '30 minutes', 'List who can help and when, including partners, relatives and friends. Plan a block of rest for the client every day. Ask about what feels hard to ask for. If the client talks about thoughts of harming themselves or the baby, address it right away in session and share that 988 (call or text) is there any time.', '[{"id": "f0", "type": "textarea", "label": "People who can help"}, {"id": "f1", "type": "textarea", "label": "Times I need rest most"}, {"id": "f2", "type": "textarea", "label": "A protected rest block"}, {"id": "f3", "type": "textarea", "label": "What I find hard to ask for"}, {"id": "f4", "type": "textarea", "label": "How I will ask"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'support', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('mom-guilt-thought-review', 'Mom Guilt Thought Review', 'cbt'::resource_kind, 'A review of guilt thoughts about parenting with a fairer look at standards.', 'Use it to help a parent look at guilt-driven thoughts about parenting.', array['Adults']::text[], '25 minutes', 'Collect the ''should'' thoughts the parent has about feeding, sleep or time. Ask where the standard comes from and how a friend would judge it. Write a fairer thought. Avoid arguing the parent out of feelings.', '[{"id": "f0", "type": "textarea", "label": "The guilt thought"}, {"id": "f1", "type": "textarea", "label": "Where the standard comes from"}, {"id": "f2", "type": "textarea", "label": "What I would tell a friend"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What I will do for myself"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('new-baby-roles-and-appreciation-talk', 'New Baby Roles and Appreciation Talk', 'couples'::resource_kind, 'A conversation guide for two partners adjusting to a new baby.', 'Use it to help partners share the load and notice each other''s efforts.', array['Couples']::text[], '40 minutes', 'Each partner lists what they are carrying and what they appreciate in the other. Then plan one change. Keep it kind. Encourage them to name needs rather than keep score.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I carry"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I carry"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I appreciate"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I appreciate"}, {"id": "f4", "type": "textarea", "label": "One change we will try"}, {"id": "f5", "type": "textarea", "label": "When we will talk again"}]'::jsonb, array['perinatal and postpartum', 'couples', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('values-in-the-fog-of-new-parenthood-page', 'Values in the Fog of New Parenthood Page', 'act'::resource_kind, 'A page for naming what matters now and tiny actions that fit.', 'Use it to help a parent connect with values when time and energy are scarce.', array['Adults']::text[], '25 minutes', 'Ask the parent what kind of parent and person they want to be. Choose one tiny action per day. Accept that some days will be survival. Check in on feelings and ask about safety when needed, mentioning 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "What I value as a parent"}, {"id": "f1", "type": "textarea", "label": "What I value as a person"}, {"id": "f2", "type": "textarea", "label": "A tiny action for today"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will be kind to myself"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('soothe-myself-between-feedings-plan', 'Soothe Myself Between Feedings Plan', 'dbt'::resource_kind, 'A plan of self-soothing through the senses for short breaks.', 'Use it to help a parent calm themselves in small windows.', array['Adults']::text[], '20 minutes', 'List sensory comforts that take under five minutes. Choose one for each of the five senses. Practice one in session. Ask where the parent can keep a small comfort kit.', '[{"id": "f0", "type": "textarea", "label": "Something to see that soothes me"}, {"id": "f1", "type": "textarea", "label": "Something to hear"}, {"id": "f2", "type": "textarea", "label": "Something to touch"}, {"id": "f3", "type": "textarea", "label": "Something to smell or taste"}, {"id": "f4", "type": "textarea", "label": "Where I will keep it"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'distress tolerance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('core-belief-evidence-journal', 'Core Belief Evidence Journal', 'cbt'::resource_kind, 'A journal collecting evidence that supports a kinder belief about oneself.', 'Use it to help a client build a fairer view of themselves over time.', array['Adults']::text[], 'Five minutes daily', 'Choose one harsh belief and a more balanced one. Each day the client writes a piece of evidence for the balanced belief. Be patient; beliefs shift slowly. Review entries and celebrate small shifts.', '[{"id": "f0", "type": "textarea", "label": "The harsh belief"}, {"id": "f1", "type": "textarea", "label": "A kinder belief I want to test"}, {"id": "f2", "type": "textarea", "label": "Evidence today for the kinder belief"}, {"id": "f3", "type": "textarea", "label": "How much I believe it from 0 to 100"}, {"id": "f4", "type": "textarea", "label": "What I will look for tomorrow"}]'::jsonb, array['self-esteem', 'core CBT', 'thinking traps']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('self-worth-is-not-a-report-card-page', 'Self-Worth Is Not a Report Card Page', 'act'::resource_kind, 'A page separating worth from performance and linking to values.', 'Use it to help a client act on values without needing a perfect score.', array['Adults']::text[], '25 minutes', 'Ask where the client learned to measure worth by results. Name a value and an action that matters regardless of outcome. Keep the tone gentle.', '[{"id": "f0", "type": "textarea", "label": "How I measure my worth"}, {"id": "f1", "type": "textarea", "label": "Where I learned that"}, {"id": "f2", "type": "textarea", "label": "What I value that is not a result"}, {"id": "f3", "type": "textarea", "label": "An action I can take no matter the outcome"}, {"id": "f4", "type": "textarea", "label": "What I say to myself when I fall short"}]'::jsonb, array['self-esteem', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('i-am-great-at-poster', 'I Am Great At Poster', 'kids'::resource_kind, 'The child makes a poster of strengths with the help of a parent''s words.', 'Use it to help a child see what they do well.', array['Children']::text[], '30 minutes', 'The child writes or draws strengths on a poster and the parent adds a note. Display it at home. Tell the parent to praise effort and character. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my poster"}, {"id": "f1", "type": "textarea", "label": "Three things I am good at"}, {"id": "f2", "type": "textarea", "label": "Something kind I did"}, {"id": "f3", "type": "textarea", "label": "What my grown-up says about me"}, {"id": "f4", "type": "textarea", "label": "Where I will hang it"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('strength-spotting-circle-game', 'Strength Spotting Circle Game', 'game'::resource_kind, 'Players spot strengths in each other with cards and give appreciations.', 'Use it to help a group notice and accept strengths.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Each player draws a strength card and offers a real appreciation to another. The receiver says thank you. Debrief on how it felt to give and to receive. Make passing available.', '[{"id": "f0", "type": "textarea", "label": "The strength I spotted"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "What I heard about myself"}, {"id": "f3", "type": "textarea", "label": "How it felt to receive"}, {"id": "f4", "type": "textarea", "label": "One strength I will own"}]'::jsonb, array['self-esteem', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('inner-critic-interview-page', 'Inner Critic Interview Page', 'worksheet'::resource_kind, 'An interview with the inner critic: what it says, why and what it is afraid of.', 'Use it to help a client understand the intent behind the critic.', array['Adults']::text[], '25 minutes', 'Ask the client to give the critic a name and ask what it wants. Often it is protecting. Then ask what a gentler coach would say. Do not try to silence it.', '[{"id": "f0", "type": "textarea", "label": "The name of my critic"}, {"id": "f1", "type": "textarea", "label": "What it says most"}, {"id": "f2", "type": "textarea", "label": "What it is trying to protect me from"}, {"id": "f3", "type": "textarea", "label": "What it costs me"}, {"id": "f4", "type": "textarea", "label": "What a kind coach would say"}]'::jsonb, array['self-esteem', 'self-compassion', 'thinking traps']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('social-prediction-test-sheet', 'Social Prediction Test Sheet', 'cbt'::resource_kind, 'A sheet for predicting how a social situation will go, then testing it.', 'Use it to help a client check predictions against what happens.', array['Adults']::text[], 'Full session', 'Pick a small social task. Record predictions, safety behaviors and outcomes. Ask what the client noticed about others. Keep tasks gradual and agreed on.', '[{"id": "f0", "type": "textarea", "label": "The social situation"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "Safety behaviors I will drop"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I noticed about other people"}, {"id": "f5", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('connection-value-single-step-page', 'Connection Value Single Step Page', 'act'::resource_kind, 'A page for choosing connection as a value and one step despite fear.', 'Use it to help a client move toward connection while anxious.', array['Adults']::text[], '25 minutes', 'Ask what connection means to the client. Pick a step like greeting someone. Name the thoughts that will come and decide to carry them. Review what happened.', '[{"id": "f0", "type": "textarea", "label": "What connection means to me"}, {"id": "f1", "type": "textarea", "label": "A small social step"}, {"id": "f2", "type": "textarea", "label": "Thoughts that will come"}, {"id": "f3", "type": "textarea", "label": "Feelings I will carry"}, {"id": "f4", "type": "textarea", "label": "What I did"}, {"id": "f5", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('opener-and-follow-up-pairing-game', 'Opener and Follow-Up Pairing Game', 'game'::resource_kind, 'Players practice starters and follow-up questions with cards.', 'Use it to help players try conversation starters in a low-stakes game.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Make cards with openers and follow-ups. Players pair up and practice for two minutes, then swap. Debrief on what felt natural. Passing is fine.', '[{"id": "f0", "type": "textarea", "label": "The opener I drew"}, {"id": "f1", "type": "textarea", "label": "How the chat went"}, {"id": "f2", "type": "textarea", "label": "A follow-up I liked"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "Where I will use it"}]'::jsonb, array['social anxiety', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('attention-inside-and-out-experiment-page', 'Attention Inside and Out Experiment Page', 'worksheet'::resource_kind, 'A page comparing focusing on oneself with focusing on the other person.', 'Use it to help a client notice how self-focus affects anxiety in conversation.', array['Adults']::text[], '25 minutes', 'Run a short conversation in session twice, once focusing inward and once outward. Rate anxiety and connection each time. Discuss what changed. Repeat outside session.', '[{"id": "f0", "type": "textarea", "label": "How I felt focusing on myself"}, {"id": "f1", "type": "textarea", "label": "How I felt focusing on the other person"}, {"id": "f2", "type": "textarea", "label": "What I noticed about the conversation"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "Where I will practice"}]'::jsonb, array['social anxiety', 'attention', 'behavioral experiment']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('interpersonal-confidence-script-card', 'Interpersonal Confidence Script Card', 'dbt'::resource_kind, 'A card with short scripts for asking, saying no and joining a group.', 'Use it to give a client words to use in social moments.', array['Adults', 'Teens']::text[], '30 minutes', 'Draft scripts with the client using DEAR MAN steps. Practice in role play. Keep scripts short and in their own voice. Give feedback on tone.', '[{"id": "f0", "type": "textarea", "label": "A situation where I want to speak up"}, {"id": "f1", "type": "textarea", "label": "What I want to say"}, {"id": "f2", "type": "textarea", "label": "How I will say it"}, {"id": "f3", "type": "textarea", "label": "My tone and posture"}, {"id": "f4", "type": "textarea", "label": "How it went in practice"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'DEAR MAN']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('grief-wave-notes', 'Grief Wave Notes', 'worksheet'::resource_kind, 'A page for noticing grief waves, what set them off and what helped.', 'Use it to help a client see grief as something that comes and goes.', array['Adults']::text[], '20 minutes', 'Ask the client to record when waves come and what comforts. Normalize that grief has no schedule. Do not push toward closure. Ask about safety if the client feels hopeless and share that 988 (call or text) is open any time.', '[{"id": "f0", "type": "textarea", "label": "When a wave came"}, {"id": "f1", "type": "textarea", "label": "What set it off"}, {"id": "f2", "type": "textarea", "label": "What it felt like"}, {"id": "f3", "type": "textarea", "label": "What helped"}, {"id": "f4", "type": "textarea", "label": "Who I reached out to"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['grief and loss', 'support', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-i-loved-and-how-i-honor-it-page', 'What I Loved and How I Honor It Page', 'act'::resource_kind, 'A page linking what the client loved about the person with ways to honor it.', 'Use it to help a client carry values and love forward after a loss.', array['Adults']::text[], '30 minutes', 'Ask what the person valued and what the client values about them. Choose one small act that honors that. Let the client set the pace and allow tears.', '[{"id": "f0", "type": "textarea", "label": "What I loved about them"}, {"id": "f1", "type": "textarea", "label": "What they valued"}, {"id": "f2", "type": "textarea", "label": "A way to honor that"}, {"id": "f3", "type": "textarea", "label": "What makes it hard"}, {"id": "f4", "type": "textarea", "label": "What I will do and when"}]'::jsonb, array['grief and loss', 'values', 'connection']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('keepsake-box-for-a-missed-person-or-pet', 'Keepsake Box for a Missed Person or Pet', 'kids'::resource_kind, 'The child decorates a box and fills it with drawings and keepsakes of someone they miss.', 'Use it to give a child a safe way to remember a person or pet.', array['Children']::text[], '30 minutes', 'The child decorates a box and picks items. Let them talk or stay quiet. Tell the parent that questions and repeated sadness are common and to answer honestly in simple words. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my memory box"}, {"id": "f1", "type": "textarea", "label": "What I put in it"}, {"id": "f2", "type": "textarea", "label": "A good memory"}, {"id": "f3", "type": "textarea", "label": "How I feel today"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('two-ways-of-mourning-partner-talk-guide', 'Two Ways of Mourning Partner Talk Guide', 'couples'::resource_kind, 'A guide for partners who grieve in different ways to share and support.', 'Use it to help partners understand each other''s different grieving.', array['Couples']::text[], '40 minutes', 'Each partner describes how they grieve and what they need. Listen without comparing. Choose one shared ritual and one space for solo time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve"}, {"id": "f2", "type": "textarea", "label": "What I need from you"}, {"id": "f3", "type": "textarea", "label": "What I find hard to see in you"}, {"id": "f4", "type": "textarea", "label": "A shared ritual"}, {"id": "f5", "type": "textarea", "label": "A way to give each other space"}]'::jsonb, array['grief and loss', 'couples', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('story-stones-remembering-game', 'Story Stones Remembering Game', 'game'::resource_kind, 'Players choose stones with pictures and share a memory or feeling.', 'Use it to help a group remember and share at their own pace.', array['Adults', 'Groups']::text[], '30 minutes', 'Paint simple pictures on stones. Players draw one and share a memory if they wish. Others listen without fixing. Debrief on what it was like.', '[{"id": "f0", "type": "textarea", "label": "The stone I drew"}, {"id": "f1", "type": "textarea", "label": "The memory it brought"}, {"id": "f2", "type": "textarea", "label": "How I felt sharing"}, {"id": "f3", "type": "textarea", "label": "What I heard from others"}, {"id": "f4", "type": "textarea", "label": "What I will take with me"}]'::jsonb, array['grief and loss', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('softened-startup-practice-sheet', 'Softened Startup Practice Sheet', 'couples'::resource_kind, 'A sheet for rewording complaints into gentle requests.', 'Use it to help partners begin tough talks with less blame.', array['Couples']::text[], '30 minutes', 'Take a complaint and rewrite it as ''I feel... about... and I need...''. Practice aloud. Give feedback on tone. Note the difference in how it lands.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my complaint as I would usually say it"}, {"id": "f1", "type": "textarea", "label": "Partner A: my softened version"}, {"id": "f2", "type": "textarea", "label": "Partner B: my complaint as I would usually say it"}, {"id": "f3", "type": "textarea", "label": "Partner B: my softened version"}, {"id": "f4", "type": "textarea", "label": "How each version felt to hear"}]'::jsonb, array['relationship issues', 'couples', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('dear-man-relationship-request-page', 'DEAR MAN Relationship Request Page', 'dbt'::resource_kind, 'A page for planning a clear, respectful request in a relationship.', 'Use it to help a client ask for what they need with skill.', array['Adults']::text[], '30 minutes', 'Walk through each step: Describe, Express, Assert, Reinforce, Mindful, Appear confident, Negotiate. Role play the request. Plan for different responses.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Describe the facts"}, {"id": "f2", "type": "textarea", "label": "Express my feelings"}, {"id": "f3", "type": "textarea", "label": "Assert what I ask"}, {"id": "f4", "type": "textarea", "label": "What I offer in return"}, {"id": "f5", "type": "textarea", "label": "How I will respond if they say no"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('guess-about-their-thoughts-ask-first-page', 'Guess About Their Thoughts Ask-First Page', 'cbt'::resource_kind, 'A page for catching assumptions about a partner''s thoughts and checking them.', 'Use it to help a client check guesses about what others think.', array['Adults']::text[], '20 minutes', 'List the assumption and how it affected behavior. Brainstorm other explanations. Plan a way to ask. Practice the question in session.', '[{"id": "f0", "type": "textarea", "label": "What I assumed"}, {"id": "f1", "type": "textarea", "label": "How it changed what I did"}, {"id": "f2", "type": "textarea", "label": "Other explanations"}, {"id": "f3", "type": "textarea", "label": "A question I can ask"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('needs-and-wants-trading-game', 'Needs and Wants Trading Game', 'game'::resource_kind, 'Players trade cards of needs and wants and discuss what they are willing to give.', 'Use it to help players talk about needs and compromise playfully.', array['Adults', 'Groups']::text[], '30 minutes', 'Make cards for needs like quiet time or affection. Players trade with partners and explain choices. Debrief on what was hard to give or ask. Keep it kind.', '[{"id": "f0", "type": "textarea", "label": "The cards I traded"}, {"id": "f1", "type": "textarea", "label": "What I asked for"}, {"id": "f2", "type": "textarea", "label": "What I gave"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "What I will try in real life"}]'::jsonb, array['relationship issues', 'game', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('closeness-and-conflict-patterns-strip', 'Closeness and Conflict Patterns Strip', 'worksheet'::resource_kind, 'A timeline of how the client has acted in past relationships and what they want next.', 'Use it to help a client see patterns and choose different steps.', array['Adults']::text[], '35 minutes', 'Ask for a few moments, not full histories. Notice patterns in how they handle closeness and conflict. Focus on what they want now and one new step.', '[{"id": "f0", "type": "textarea", "label": "Moments that stand out"}, {"id": "f1", "type": "textarea", "label": "Patterns I notice"}, {"id": "f2", "type": "textarea", "label": "What I did well"}, {"id": "f3", "type": "textarea", "label": "What I want to do differently"}, {"id": "f4", "type": "textarea", "label": "One new step"}]'::jsonb, array['relationship issues', 'patterns', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('today-s-safe-people-and-places-plan-page', 'Today''s Safe People and Places Plan Page', 'worksheet'::resource_kind, 'A page naming safe people, places and steps without recounting any events.', 'Use it to help a client build a current-day plan for safety and support.', array['Adults', 'Teens']::text[], '30 minutes', 'Focus on the present: who is safe, where, and what to do when feeling unsafe. Never ask for details of the past. Check reporting duties if the client is a minor. Share that 988 (call or text) is available any time, and RAINN at 800-656-4673.', '[{"id": "f0", "type": "textarea", "label": "People I trust"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe"}, {"id": "f2", "type": "textarea", "label": "What I do when I feel unsafe"}, {"id": "f3", "type": "textarea", "label": "Who I can call"}, {"id": "f4", "type": "textarea", "label": "Steps for a hard day"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('grounding-and-pacing-skills-menu', 'Grounding and Pacing Skills Menu', 'dbt'::resource_kind, 'A menu of grounding and pacing skills to use before and after session.', 'Use it to help a client slow down and stay present.', array['Adults']::text[], '25 minutes', 'Try several skills in session and let the client rate them. Agree on a pace and a stop signal. Nothing here asks for details of what happened. Check in at the end.', '[{"id": "f0", "type": "textarea", "label": "Skills that ground me"}, {"id": "f1", "type": "textarea", "label": "Skills that help me slow down"}, {"id": "f2", "type": "textarea", "label": "My stop signal"}, {"id": "f3", "type": "textarea", "label": "What I do after a session"}, {"id": "f4", "type": "textarea", "label": "Who I can contact"}]'::jsonb, array['sexual abuse', 'grounding', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('reclaiming-choices-values-page', 'Reclaiming Choices Values Page', 'act'::resource_kind, 'A page about choices the client can make now that fit their values.', 'Use it to help a client notice choice and agency in daily life.', array['Adults']::text[], '30 minutes', 'Invite the client to list small daily choices that are theirs. Link to values. Go slowly and let them skip anything. Never ask about past events.', '[{"id": "f0", "type": "textarea", "label": "Small choices that are mine"}, {"id": "f1", "type": "textarea", "label": "What I value"}, {"id": "f2", "type": "textarea", "label": "A choice I want to make this week"}, {"id": "f3", "type": "textarea", "label": "What supports me"}, {"id": "f4", "type": "textarea", "label": "What I will do if it feels hard"}]'::jsonb, array['sexual abuse', 'values', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-safety-rules-drawing', 'Body Safety Rules Drawing', 'kids'::resource_kind, 'The child draws the people and rules that keep their body safe and who to tell.', 'Use it to help a child learn safety rules and trusted adults.', array['Children']::text[], '25 minutes', 'Use simple, age-appropriate language: my body belongs to me, and I can always tell a trusted adult. Do not ask for details. Tell the parent how to respond calmly if a child shares. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw me and my safe grown-ups"}, {"id": "f1", "type": "textarea", "label": "Who I can tell"}, {"id": "f2", "type": "textarea", "label": "The rule about my body"}, {"id": "f3", "type": "textarea", "label": "What I do if someone makes me feel unsafe"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fair-thoughts-about-blame-cards', 'Fair Thoughts About Blame Cards', 'cbt'::resource_kind, 'Cards for gently looking at self-blame thoughts and finding fairer ones.', 'Use it to help a client meet self-blame thoughts with kindness.', array['Adults']::text[], '25 minutes', 'Work only with thoughts, not events. Ask the client what they would tell a friend. Write a fairer thought and practice reading it. Skip if the client feels unsteady. Share that 988 (call or text) is available.', '[{"id": "f0", "type": "textarea", "label": "A blame thought that visits me"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f2", "type": "textarea", "label": "A fairer thought"}, {"id": "f3", "type": "textarea", "label": "How I feel reading it"}, {"id": "f4", "type": "textarea", "label": "Who supports me"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('tipp-skills-practice-log', 'TIPP Skills Practice Log', 'dbt'::resource_kind, 'A log for practicing temperature, intense exercise, paced breathing and relaxation.', 'Use it to help a client try body-based skills for fast relief.', array['Adults']::text[], 'One week, ten minutes per entry', 'Teach each skill and rate it in session. Ask the client to log use and effect. Check for health issues before temperature or exercise skills.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Which TIPP skill I used"}, {"id": "f2", "type": "textarea", "label": "Distress before"}, {"id": "f3", "type": "textarea", "label": "Distress after"}, {"id": "f4", "type": "textarea", "label": "What I would change"}]'::jsonb, array['coping skills', 'distress tolerance', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('room-hunt-for-everyday-calm-tools', 'Room Hunt for Everyday Calm Tools', 'game'::resource_kind, 'Players hunt for items and places that support coping skills and share how they use them.', 'Use it to help players find coping tools around them.', array['Teens', 'Adults', 'Groups']::text[], '35 minutes', 'Make a list like something soft, something that smells nice, a quiet spot. Players find them and explain use. Debrief on which they will use.', '[{"id": "f0", "type": "textarea", "label": "What I found"}, {"id": "f1", "type": "textarea", "label": "How I could use it"}, {"id": "f2", "type": "textarea", "label": "What surprised me"}, {"id": "f3", "type": "textarea", "label": "What I will keep"}, {"id": "f4", "type": "textarea", "label": "Where I will use it"}]'::jsonb, array['coping skills', 'game', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('decorate-and-fill-my-calm-tool-box', 'Decorate and Fill My Calm Tool Box', 'kids'::resource_kind, 'The child decorates a box and fills it with coping tools they pick.', 'Use it to help a child build a personal set of coping tools.', array['Children']::text[], '30 minutes', 'The child decorates a box and adds drawings or small items like a stress ball. Practice using each. Tell the parent to keep it handy. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my toolbox"}, {"id": "f1", "type": "textarea", "label": "Tools I put in"}, {"id": "f2", "type": "textarea", "label": "Which tool I use first"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}, {"id": "f4", "type": "textarea", "label": "How my grown-up helps"}]'::jsonb, array['coping skills', 'children', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('hard-moment-to-skill-pairing-chart', 'Hard Moment to Skill Pairing Chart', 'worksheet'::resource_kind, 'A chart matching feelings and situations with coping skills.', 'Use it to help a client match skills to what they face.', array['Adults', 'Teens']::text[], '25 minutes', 'List common difficult moments and brainstorm skills. Rate each match from 0 to 10. Revise after trying them.', '[{"id": "f0", "type": "textarea", "label": "A hard situation"}, {"id": "f1", "type": "textarea", "label": "Skills that might fit"}, {"id": "f2", "type": "textarea", "label": "My rating of each"}, {"id": "f3", "type": "textarea", "label": "The one I will try"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['coping skills', 'skills', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('willingness-to-feel-practice-page', 'Willingness to Feel Practice Page', 'act'::resource_kind, 'A page practicing making room for a feeling for a short time.', 'Use it to help a client build willingness to feel without escape.', array['Adults']::text[], '20 minutes', 'Choose a mild feeling and have the client stay with it for a minute, noticing sensations. Rate willingness. Debrief gently.', '[{"id": "f0", "type": "textarea", "label": "The feeling I picked"}, {"id": "f1", "type": "textarea", "label": "Where I notice it"}, {"id": "f2", "type": "textarea", "label": "How willing I was"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "How I might use this"}]'::jsonb, array['coping skills', 'willingness', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('feared-situations-rung-ranking-page', 'Feared Situations Rung Ranking Page', 'cbt'::resource_kind, 'A ladder of feared situations ranked from easiest to hardest.', 'Use it to help a client plan gradual steps toward a feared situation.', array['Adults']::text[], 'Full session', 'List situations and rate fear for each. Pick a first step that is challenging but doable. Plan how to stay in it. Agree on pacing together.', '[{"id": "f0", "type": "textarea", "label": "The fear I want to work on"}, {"id": "f1", "type": "textarea", "label": "Situations ranked by fear"}, {"id": "f2", "type": "textarea", "label": "My first step"}, {"id": "f3", "type": "textarea", "label": "How long I will stay"}, {"id": "f4", "type": "textarea", "label": "What I notice after"}]'::jsonb, array['phobias', 'exposure', 'avoidance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('sticker-ladder-of-brave-small-steps', 'Sticker Ladder of Brave Small Steps', 'kids'::resource_kind, 'The child decorates a ladder with small brave steps and stickers.', 'Use it to help a child take small steps toward something scary.', array['Children']::text[], '25 minutes', 'The child draws a ladder with steps from easy to hard. Add stickers after each step. Tell the parent to cheer effort and never force a step. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my ladder"}, {"id": "f1", "type": "textarea", "label": "My first step"}, {"id": "f2", "type": "textarea", "label": "Who helps me"}, {"id": "f3", "type": "textarea", "label": "How I feel after a step"}, {"id": "f4", "type": "textarea", "label": "What I get to do after"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fear-facing-board-game', 'Fear Facing Board Game', 'game'::resource_kind, 'Players move along a board and take on small fear-facing challenges.', 'Use it to help a group try small exposures with support.', array['Teens', 'Adults', 'Groups']::text[], '40 minutes', 'Create a board with challenge squares at mild levels. Players choose challenges and cheer each other. Debrief on what it was like. Always allow a pass.', '[{"id": "f0", "type": "textarea", "label": "The challenge I took"}, {"id": "f1", "type": "textarea", "label": "How scared I felt"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "The next challenge"}]'::jsonb, array['phobias', 'game', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-i-skip-because-of-fear-map', 'What I Skip Because of Fear Map', 'worksheet'::resource_kind, 'A map of things the client avoids because of a fear and what it costs.', 'Use it to help a client see how avoidance shapes daily life.', array['Adults']::text[], '25 minutes', 'List places and activities avoided. Ask what each costs. Choose one to work toward. Keep non-judgmental.', '[{"id": "f0", "type": "textarea", "label": "Things I avoid"}, {"id": "f1", "type": "textarea", "label": "What I miss out on"}, {"id": "f2", "type": "textarea", "label": "What I fear will happen"}, {"id": "f3", "type": "textarea", "label": "One thing I want back"}, {"id": "f4", "type": "textarea", "label": "A first step"}]'::jsonb, array['phobias', 'avoidance', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fear-and-values-crossroads-page', 'Fear and Values Crossroads Page', 'act'::resource_kind, 'A page for choosing values-led action when fear points elsewhere.', 'Use it to help a client choose a valued direction with fear present.', array['Adults']::text[], '25 minutes', 'Draw a crossroads with fear on one path and values on the other. Discuss what each gives. Choose a step and plan to carry the fear.', '[{"id": "f0", "type": "textarea", "label": "What fear tells me to do"}, {"id": "f1", "type": "textarea", "label": "What my values point to"}, {"id": "f2", "type": "textarea", "label": "The cost of each path"}, {"id": "f3", "type": "textarea", "label": "The step I will take"}, {"id": "f4", "type": "textarea", "label": "What I will carry with me"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-talk-thought-record', 'Body Talk Thought Record', 'cbt'::resource_kind, 'A thought record for noticing critical thoughts about the body and shifting them.', 'Use it to help a client catch critical body thoughts and find a fairer view.', array['Adults']::text[], '25 minutes', 'Ask the client to notice when body thoughts spike and what was happening. Write a fairer thought focusing on what the body does. Avoid discussing size, shape or appearance rules.', '[{"id": "f0", "type": "textarea", "label": "Where I was when the thought came"}, {"id": "f1", "type": "textarea", "label": "The thought"}, {"id": "f2", "type": "textarea", "label": "How it made me feel"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What my body did for me today"}]'::jsonb, array['body image', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-as-a-home-values-page', 'Body as a Home Values Page', 'act'::resource_kind, 'A page about caring for and appreciating the body as the home where life happens.', 'Use it to help a client act on values rather than appearance.', array['Adults']::text[], '25 minutes', 'Ask what the client''s body lets them do. Link to values and plan one caring act. Keep focus on function and care.', '[{"id": "f0", "type": "textarea", "label": "What my body lets me do"}, {"id": "f1", "type": "textarea", "label": "What I value"}, {"id": "f2", "type": "textarea", "label": "One caring act this week"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will notice"}]'::jsonb, array['body image', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-judgment-letting-go-practice', 'Body Judgment Letting-Go Practice', 'dbt'::resource_kind, 'A mindfulness practice for noticing body judgments without acting on them.', 'Use it to help a client observe judgments and return to the present.', array['Adults']::text[], '20 minutes', 'Teach non-judgmental stance. Have the client notice a judgment, label it ''judgment'' and return to the senses. Practice in session.', '[{"id": "f0", "type": "textarea", "label": "A judgment I noticed"}, {"id": "f1", "type": "textarea", "label": "How I labeled it"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my senses"}, {"id": "f3", "type": "textarea", "label": "How I returned"}, {"id": "f4", "type": "textarea", "label": "When I will practice"}]'::jsonb, array['body image', 'core DBT', 'mindfulness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('appreciation-for-who-we-are-exchange', 'Appreciation for Who We Are Exchange', 'couples'::resource_kind, 'Partners trade appreciation about character and shared moments, not looks.', 'Use it to help partners value each other beyond appearance.', array['Couples']::text[], '25 minutes', 'Each writes appreciations about qualities and actions. Read aloud and receive. Debrief on what it felt like. Keep appearance out.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciate about my partner"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciate about my partner"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear"}, {"id": "f3", "type": "textarea", "label": "A moment I treasure"}, {"id": "f4", "type": "textarea", "label": "How we will keep it up"}]'::jsonb, array['body image', 'couples', 'connection']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-my-body-does-collage', 'What My Body Does Collage', 'kids'::resource_kind, 'The child makes a collage of all the things their body does and loves.', 'Use it to help a child value what their body can do.', array['Children']::text[], '30 minutes', 'The child cuts pictures or draws activities like running, hugging and laughing. Tell the parent to talk about what bodies do, not how they look. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my collage"}, {"id": "f1", "type": "textarea", "label": "Things my body does"}, {"id": "f2", "type": "textarea", "label": "My favorite"}, {"id": "f3", "type": "textarea", "label": "How my body helps me"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says"}]'::jsonb, array['body image', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz)
